insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('si-a-bia-ind-veenan-haun', 'si a Bia ind Veenan haun', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich ein Bier in die Venen hauen', '[{"kategorie": "wörtlich", "text": "\"sich ein Bier in die Blutbahn schieben\""}, {"kategorie": "", "text": "\"sich ein Kaltgetränk hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich ''ne Halbe intravenös zuführen\""}]'::jsonb, 'Noch dera Hockn muass I ma easchd amoi drei Bia ind Veenan haun!'),
  ('noch-dera-hockn-muass-i-ma-easchd-amoi-drei-bia-ind-veenan-haun', 'Noch dera Hockn muass I ma easchd amoi drei Bia ind Veenan haun!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach dieser Hack''n muss ich mir erst mal drei Bier in die Venen hau''n!', '[{"kategorie": "wörtlich", "text": "\"Nach so viel Malochen muss ich mir erst mal drei Kaltgetränke reinziehen!\"  2. Nach dieser Plackerei muss ich mir erst mal ein paar Halbe hinter die Binde kippen!  3. Nach dem Tag brauch ich ’ne Hopfeninfusion in dreifacher Dosis!"}]'::jsonb, 'si a Bia ind Veenan haun'),
  ('si-an-brennoowi-ind-veenan-haun', 'si an Brennoowi ind Veenan haun', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einen Brennrunter in die Venen hauen', '[{"kategorie": "wörtlich", "text": "\"sich einen Schnaps in die Blutbahn schieben\""}, {"kategorie": "", "text": "\"sich was Hochprozentiges hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich ein Fläschchen Bier intravenös zuführen\""}]'::jsonb, 'Zum Fruaschduck hau I ma an Brennoowi ind Veenan, wäu dea weckd mi easchd so richtig auf!'),
  ('zum-fruaschduck-hau-i-ma-an-brennoowi-ind-veenan-waeu-dea-weckd-mi-easchd-so-richtig-auf', 'Zum Fruaschduck hau I ma an Brennoowi ind Veenan, wäu dea weckd mi easchd so richtig auf!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Zum Frühstück hau ich mir einen ''Brennrunter'' in die Venen, weil der weckt mich erst so richtig auf!', '[{"kategorie": "wörtlich", "text": "\"Zum Frühstück hau ich mir ein Schnapserl in die Venen, weil das weckt mich erst so richtig auf!\"  2. Zum Frühstück drück ich mir ein Stamperl in die Blutbahn – Kaffee ist für Anfänger!  3. Zum Aufstehen stoß ich mir ein Schnapserl in die Venen – damit die Welt wieder gerade steht!"}]'::jsonb, 'si an Brennoowi ind Veenan haun'),
  ('si-an-brennoowi-in-d-figua-schdessn', 'si an Brennoowi in d''Figua schdessn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einen Brennrunter in die Figur stoßen', '[{"kategorie": "wörtlich", "text": "\"sich einen Schnaps hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich einen Schnaps hinter die Kulissen schieben\""}, {"kategorie": "", "text": "sich einen Schnaps in die Venen hauen"}, {"kategorie": "", "text": "sich ein Schnapserl [[ins]] Hirn stoßen"}]'::jsonb, 'Zum Aufwochn schdess I ma an Brennoowi ind Figua - des is mei Prophylaxe geengan Oitoog!'),
  ('zum-aufwochn-schdess-i-ma-an-brennoowi-ind-figua-des-is-mei-prophylaxe-geengan-oitoog', 'Zum Aufwochn schdess I ma an Brennoowi ind Figua - des is mei Prophylaxe geengan Oitoog!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Zum Aufwachen stoß ich mir einen ''Brennrunter'' in die Figur - das ist meine Prophylaxe gegen den Alltag!', '[{"kategorie": "wörtlich", "text": "\"Zum Aufwachen stoß ich mir ein Schnapserl in die Figur - das ist meine Prophylaxe gegen den Alltag!\"  2. Zum Munterwerden geb ich mir ein Stamperl intravenös – das hilft am allerbesten gegen den Alltag!  3. Morgens knall ich mir erst mal einen Kurzen rein – das bringt mich auf Betriebstemperatur für den bevorstehenden Tag!"}]'::jsonb, 'si an Brennoowi in d''Figua schdessn'),
  ('si-wos-ins-hian-schdessn', 'si wos ins Hian schdessn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich was ins Hirn stoßen', '[{"kategorie": "wörtlich", "text": "\"sich was ins Hirn schießen\""}, {"kategorie": "scherzhaft für", "text": "\"sich das Hirn ölen\""}, {"kategorie": "", "text": "sich Alkoholisches [[in]] die Venen hauen"}, {"kategorie": "", "text": "sich einen hinter die Binde kippen"}, {"kategorie": "", "text": "sich was Hochprozentiges [[in]] die Figur stoßen"}]'::jsonb, 'Ob und zua muassd da wos ins Hian schdessn - zua innaren Schdabilisiirung!'),
  ('ob-und-zua-muassd-da-wos-ins-hian-schdessn-zua-innaren-schdabilisiirung', 'Ob und zua muassd da wos ins Hian schdessn - zua innaren Schdabilisiirung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ab und zu musst du dir was ins Hirn stoßen – zur inneren Stabilisierung!', '[{"kategorie": "wörtlich", "text": "\"Ab und zu musst du dir was ins Hirn schießen – zur inneren Stabilisierung!\"  Ab und zu muss du dir Hirnbenzin in die Blutbahn drücken – sonst dreht der Kopf durch!  3. Ich sag’s dir: Manchmal musst du den Schädel betanken – für die Nerven!"}]'::jsonb, 'si wos ins Hian schdessn'),
  ('si-wos-ins-gsichd-schdessn', 'si wos ins Gsichd schdessn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich was ins Gesicht stoßen', '[{"kategorie": "wörtlich", "text": "\"sich was in die Birne schießen\""}, {"kategorie": "scherzhaft für", "text": "\"sich die Gurgel ölen\""}, {"kategorie": "", "text": "sich Alkoholisches [[in]] die Venen hauen"}, {"kategorie": "", "text": "sich einen hinter die Binde kippen"}, {"kategorie": "", "text": "sich was Hochprozentiges [[in]] die Figur stoßen"}]'::jsonb, 'Ma muass si an Doppla ins Gsichd schdessn - daunn find ma dei Oide viileichd schee!'),
  ('ma-muass-si-an-doppla-ins-gsichd-schdessn-daunn-find-ma-dei-oide-viileichd-schee', 'Ma muass si an Doppla ins Gsichd schdessn - daunn find ma dei Oide viileichd schee!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Man muss sich einen Doppler ins Gesicht stoßen - dann findet man deine Alte vielleicht schön!', '[{"kategorie": "wörtlich", "text": "\"Man muss sich einen Doppelliter Wein hinter die Binde kippen  - dann findet man deine Alte vielleicht schön!\"  2. Da muss man sich schon zwei Liter Wein reinballern, bevor man die Visage deiner Alten schön findet!  3. Du musst deine Alte schönsaufen - nach dem zweiten Liter sieht ihr Gesicht bestimmt erträglicher aus!"}]'::jsonb, ''),
  ('schdess-ma-uns-a-butoeoen-ins-hian', 'Schdess ma uns a Butöön ins Hian!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Stoßen wir uns eine Bouteille ins Hirn!', '[{"kategorie": "wörtlich", "text": "\"Kippen wir uns ''ne Bouteille hinter die Binde!\"  2. \"Hauen wir uns eine Bouteille in die Venen!\"  3. \"Stoßen wir uns ''ne Flasche Wein in die Figur!\"  4. \"Schieben wir uns ''ne Flasche Wein in die Blutbahn!"}]'::jsonb, ''),
  ('schdess-ma-uns-an-doppla-ins-gsichd', 'Schdess ma uns an Doppla ins Gsichd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Stoßen wir uns einen Doppler ins Gesicht!', '[{"kategorie": "wörtlich", "text": "\"Kippen wir uns ''n Doppelliter Wein hinter die Binde!\"  2. \"Hauen wir uns einen Doppler in die Venen!\"  3. \"Stoßen wir uns ''nen Doppler Wein in die Figur!\"  4. \"Schieben wir uns ''ne Doppelliterflasche Wein in die Blutbahn!"}]'::jsonb, ''),
  ('si-aan-ind-figua-schdessn', 'si aan ind Figua schdessn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einen in die Figur stoßen', '[{"kategorie": "wörtlich", "text": "\"sich einen hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich einen hinter die Kulissen schieben\""}, {"kategorie": "", "text": "\"sich einen in die Venen hauen\""}]'::jsonb, 'Bevua ma haamgee, schdess ma uns noo aan ind Figua!'),
  ('bevua-ma-haamgee-schdess-ma-uns-noo-aan-ind-figua', 'Bevua ma haamgee, schdess ma uns noo aan ind Figua!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bevor wir heimgehen, stoßen wir uns noch einen in die Figur!', '[{"kategorie": "wörtlich", "text": "\"Bevor wir heimgehen, kippen wir uns noch einen hinter die Binde!\"  2. Bevor wir abdüsen, klatschen wir uns noch einen rein!  3. Wär schade, nüchtern heimzugehen – also, einer geht noch!"}]'::jsonb, 'si aan ind Figua schdessn'),
  ('si-aan-ind-figua-schiassn', 'si aan ind Figua schiassn', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einen in die Figur schießen', '[{"kategorie": "wörtlich", "text": "\"sich einen hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich einen hinter die Kulissen schieben\""}, {"kategorie": "", "text": "\"sich einen in die Venen hauen\""}]'::jsonb, 'I gib ma ned de Kuugl - I schiass ma liawa aan noochn aundan ind Figua!'),
  ('i-gib-ma-ned-de-kuugl-i-schiass-ma-liawa-aan-noochn-aundan-ind-figua', 'I gib ma ned de Kuugl - I schiass ma liawa aan noochn aundan ind Figua!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich geb mir nicht die Kugel - ich schieß mir lieber einen nach dem anderen in die Figur!', '[{"kategorie": "wörtlich", "text": "\"Ich geb mir nicht die Kugel - ich schieß mir lieber einen nach dem anderen hinter die Binde!\"  2. Ich ballere mir lieber Schnaps ins System als Blei in den Kopf!  3. Ich schieß mir nicht die Birne weg – sondern lieber einen nach dem anderen über die Leber!"}]'::jsonb, 'si aan ind Figua schiassn'),
  ('si-aan-hintad-kulissn-schiam', 'si aan hintad Kulissn schiam', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einen hinter die Kulissen schieben', '[{"kategorie": "wörtlich", "text": "\"sich einen hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich einen in die Figur schießen\""}, {"kategorie": "", "text": "\"sich einen in die Venen hauen\""}]'::jsonb, 'Je öödasd wiasd, umso efta muassda aan hintad Kulissn schiam!'),
  ('je-oeoedasd-wiasd-umso-efta-muassda-aan-hintad-kulissn-schiam', 'Je öödasd wiasd, umso efta muassda aan hintad Kulissn schiam!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Je älter du wirst, umso öfter musst du dir einen hinter die Kulissen schieben!', '[{"kategorie": "wörtlich", "text": "\"Je älter du wirst, umso öfter musst du dir einen hinter die Binde kippen!\"  2. Je älter du wirst, umso öfter musst du dir Hirnbenzin in die Blutbahn schießen!  3. Ab einem gewissen Alter ist der Schnaps keine Sünde mehr, sondern Medizin!  4. Je älter du wirst, desto öfter verlangt die Seele nach Hochprozentigem!"}]'::jsonb, 'si aan hintad Kulissn schiam'),
  ('si-aan-ind-venan-haun', 'si aan ind Venan haun', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einen in die Venen hauen', '[{"kategorie": "wörtlich", "text": "\"sich einen in die Blutbahn schießen\""}, {"kategorie": "", "text": "\"sich einen hinter die Binde kippen\""}, {"kategorie": "", "text": "\"sich einen hinter die Kulissen schieben\""}, {"kategorie": "", "text": "\"sich einen in die Fugur stoßen\""}]'::jsonb, 'Si aan noochn aundan ind Veenan haun, tuad guad - zumindast, bisd Vanunft wiida eikeead!'),
  ('si-aan-noochn-aundan-ind-veenan-haun-tuad-guad-zumindast-bisd-vanunft-wiida-eikeead', 'Si aan noochn aundan ind Veenan haun, tuad guad - zumindast, bisd Vanunft wiida eikeead!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sich einen nach dem anderen in die Venen hauen, tut gut - zumindest, bis die Vernunft wieder einkehrt!', '[{"kategorie": "wörtlich", "text": "\"Sich einen Schuss Hirnbenzin nach dem anderen in die Blutbahnzu jagen, tut gut – zumindest, bis die Realität wiederkommt!\"  2. Das beste am Rausch ist die Pause vom Denken - bis der Kater kommt!  3. Sich einen Kick nach dem anderen reinziehen, tut schon gut – zumindest, bis der Verstand wieder anklopft!"}]'::jsonb, 'si aan ind Venan haun'),
  ('a-glaasal-wei', 'A Glaasal Wei!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Gläschen Wein!', '[{"kategorie": "wörtlich", "text": "\"Ein kleines Glas Wein!\" (Bestellt man in Wien \"ein Glaserl Wein\" erhält man - wenn nicht nachgefragt wird - im Üblichen \"ein Achtelliter Wein\" serviert)  2. \"Ein [[Achterl]] Wein!\"  3. \"Ein Achtelliter Wein!\""}]'::jsonb, ''),
  ('a-glaasal-wei-muass-sei-waeu-nuechtan-bin-i-a-gsundheitsrisiko-fiad-gsoeoeschoft', 'A Glaasal Wei muass sei - wäu nüchtan bin I a Gsundheitsrisiko fiad Gsööschoft!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Glaserl Wein muss sein - weil nüchtern bin ich ein Gesundheitsrisiko für die Gesellschaft!', '[{"kategorie": "wörtlich", "text": "\"\"Ein Glaserl Wein muss sein - weil nüchtern bin ich nicht gesellschaftstauglich!\"  2. Ein Glaserl Wein muss sein – denn mein soziales Benehmen ist alkoholabhängig!  3. Ein Glaserl Wein muss sein – weil die Gesellschaft nüchtern einfach nicht auszuhalten ist!"}]'::jsonb, 'A Glaasal Wei!'),
  ('de-jugend-von-heit-sumpad-ned-de-tschueued', 'De Jugend von heit sumpad ned - de tschüüd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Die Jugend von heute sumpert nicht - die chillt!', '[{"kategorie": "wörtlich", "text": "\"Die Jugend von heute liegt nicht faul herum – die betreibt aktives Chillen!\"  2. Was früher Sumpern war, heißt heute ''Digital Detox'' auf der Couch!  3. Die neue Generation liegt nicht brach – sie lebt bewusst im Zustand der Entschleunigung!"}]'::jsonb, ''),
  ('dea-sumpad-in-gaunzn-toog-dahii-wiara-schdingads-gsoeoechds', 'Dea sumpad in gaunzn Toog dahii wiara schdingads Gsööchds!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der sumpert den ganzen Tag dahin wie ein stinkendes Geselchtes!', '[{"kategorie": "wörtlich", "text": "\"Der liegt den ganzen Tag herum wie ein faulendes Stück Selchfleisch!\"  2. Der fault auf der Couch vor sich hin wie ein altes Geselchtes!  3. Der vegetiert den ganzen Tag dahin wie vergorenes Fleisch!"}]'::jsonb, ''),
  ('ma-kau-schoo-moi-tschueuen-owa-dea-vasumpad-jo-wiara-toods-fleisch-auf-da-kautsch', 'Ma kau schoo moi tschüün - owa dea vasumpad jo wiara toods Fleisch auf da Kautsch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Man kann schon mal chillen - aber der versumpert ja wie ein totes Fleisch auf der Couch!', '[{"kategorie": "wörtlich", "text": "\"Ein bisschen chillen ist okay - aber der vergammelt ja wie totes Fleisch auf der Couch!\"  2. Pause machen schön und gut – aber der verwest ja regelrecht in der Couch!  3. Abhängen soll sein – aber was der macht, grenzt an lebendige Mumifizierung!"}]'::jsonb, ''),
  ('wia-san-beim-wiatn-voi-vasumpad-nooch-zeen-gschbritzde-haed-i-fost-de-koeoenarin-gheirat', 'Wia san beim Wiatn voi vasumpad - nooch zeen Gschbritzde häd I fost de Köönarin gheirat!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wir sind beim Wirten voll versumpert - nach zehn Gespritzten hätt'' ich fast die Kellnerin geheiratet!', '[{"kategorie": "wörtlich", "text": "\"Wir sind beim Wirten komplett versandelt - nach zehn Gläsern Spritzwein hab ich der Kellnerin sogar ''nen Heiratsantrag gemacht!\"  2. Wir sind beim Wirten total versumpft - zum Schluss hab ich sogar um die Hand der Kellnerin angehalten!  3. Wir sind beim Wirten voll versackt - am Schluss hab ich die Kellnerin sogar für meine große Liebe gehalten!"}]'::jsonb, ''),
  ('im-zuaschdaund-da-vasumparung-vageen-de-schdundn-wia-sekundn-de-kautsch-wiad-zua-aussnwoeoed-und-netflix-zua-religion', 'Im Zuaschdaund da Vasumparung vageen de Schdundn wia Sekundn - de Kautsch wiad zua Aussnwööd, und Netflix zua Religion!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Im Zustand der Versumperung vergehen Stunden wie Sekunden – die Couch wird zur Außenwelt, und Netflix zur Religion!', '[{"kategorie": "wörtlich", "text": "Im Zustand des gepflegten Gammelns fliegt die Zeit davon - das Sofa ersetzt die Außenwelt, und Netflix die Religion!  2. Im Modus der Versumperung wird der Hintern schwer, die Gedanken leicht, und die Welt reduziert sich auf Bildschirmgröße!  3. Im Zustand geistiger Verwesung schmilzt die Zeit dahin - der Wille schwindet und man chillt sich mit Netflix durchs Leben auf der faulen Haut!"}]'::jsonb, ''),
  ('da-groosse-sumpa-vom-groossvoodan-schdeed-no-imma-neeman-oofn-raundvoi-mit-brennhoiz-und-oide-gschichdn', 'Da groosse Sumpa vom Groossvoodan schdeed no imma neeman Oofn - raundvoi mit Brennhoiz und oide Gschichdn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der große Sumper vom Großvater steht noch immer neben dem Ofen, randvoll mit Brennholz und alten Geschichten!', '[{"kategorie": "wörtlich", "text": "\"Der große, geflochtene Strohkorb vom Großvater steht noch immer beim Ofen, bis zum Rand gefüllt mit Feuerholz und alten Geschichten!\"  2. Neben dem Ofen steht nach wie vor Großvaters großer Holzkorb – voll bis obenhin mit Brennholz und alten Geschichten!  3. Opas großer Brennholzkorb steht immer noch wie ein Denkmal neben dem Ofen – voller Scheite und Geschichten!"}]'::jsonb, ''),
  ('de-woasoogarin-trommaed-mit-ian-sumpa-unsare-spiritistischn-sitzungan-ei', 'De Woasoogarin trommäd mit ian Sumpa unsare spiritistischn Sitzungan ei!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Die Wahrsagerin trommelt mit ihrem Sumper unsere spiritistischen Sitzungen ein!', '[{"kategorie": "wörtlich", "text": "\"Die Wahrsagerin eröffnet unsere spiritistischen Sitzungen stets mit ihrer Handtrommel!\"  2. Mit ihrer kleinen Rahmentrommel gibt die Wahrsagerin das Zeichen zum Beginn unserer Séancen!  3. Mit dumpfem Trommelschlag öffnet uns die Schamanin das Tor zum Jenseits!"}]'::jsonb, ''),
  ('oida-des-is-a-sumpa-wiara-im-biachl-schdeed-a-musta-oone-foab', 'Oida, des is a Sumpa, wiara im Biachl schdeed - a Musta oone Foab!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alter, das ist ein Sumper, wie er im Büchl steht - ein Muster ohne Farbe!', '[{"kategorie": "wörtlich", "text": "\"Mann, das ist ein Langweiler, wie er im Buche steht - ein Muster ohne Farbe!\"  2. Mann, was für ein Langweiler - der hat ein Gesicht wie ein Teebeutel nach’m dritten Aufguss!  3. Was für ein Lahmlackl - wenn man das Wort ''fad'' googelt, kommt sein Gesicht!"}]'::jsonb, ''),
  ('dea-sumpara-is-laungwaeulich-bis-unta-de-knochn-mea-duachschnitt-geed-ned', 'Dea Sumpara is laungwäulich bis unta de Knochn - mea Duachschnitt geed ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Sumperer ist langweilig bis unter die Knochen - mehr Durchschnitt geht nicht!', '[{"kategorie": "wörtlich", "text": "Dieser  Lahmlackl ist langweilig bis ins Mark - fader geht''s nicht mehr!  2. Der Typ ist sowas von einem Langweiler - ein leeres Blatt Papier hat mehr Spannung als der!  3. Mann, was ist der Typ doch für ein Lahmlackl - der hat ein Gesicht wie ein Teebeutel nach’m dritten Aufguss!"}]'::jsonb, ''),
  ('dahaam2', 'Dahaam2', 'das', '', '', 'Grundwortschatz Wienerisch', 'Daheim', '[{"kategorie": "wörtlich", "text": "\"Daheim\" (vom mittelhochdeutschen \"dā heime\"=\"daheim\")"}, {"kategorie": "allg.", "text": "\"das Daheim\", \"das Zuhause\", \"das Heim\", [[Buudn]]"}]'::jsonb, 'Mei Dahaam is a Mischung aus Schlochtfööd, Wäschbeag und Bialooga!'),
  ('mei-dahaam-is-a-mischung-aus-schlochtfoeoed-waeschbeag-und-bialooga', 'Mei Dahaam is a Mischung aus Schlochtfööd, Wäschbeag und Bialooga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Daheim ist eine Mischung aus Schlachtfeld, Wäscheberg und Bierlager!', '[{"kategorie": "wörtlich", "text": "\"Mein Daheim gleicht einer Mischung aus Kriegsschauplatz, Kleiderlawine und Hopfenlager!\"  2. Meine Bude ist irgendwo zwischen Schlachtfeld, Textilhölle und Getränkemarkt angesiedelt!\"  3. Mein Zuhause? Ein Kompromiss aus Textildschungel, Dauerkrieg und Bierparadies!"}]'::jsonb, ''),
  ('dahaam-is-dahaam', 'Dahaam is dahaam!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Daheim ist daheim!', '[{"kategorie": "wörtlich", "text": "\"Zuhause bleibt Zuhause!\"  2. Nirgends ist es so schön wie daheim!  3. Daheim ist da, wo die Seele zur Ruhe kommt!"}]'::jsonb, ''),
  ('dahaam-do-bin-i-keenich', 'Dahaam do bin I Keenich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Daheim da bin ich König!', '[{"kategorie": "wörtlich", "text": "\"Zuhause bin ich der Herr im Haus!\"  2. In meinen vier Wänden hab ich das Sagen!  3. Daheim regier ich – ganz ohne Krone!"}]'::jsonb, ''),
  ('samma-in-da-kindakrippn-oda-kriag-i-jetzt-endlich-an-gscheidn-schdaumpa', 'Samma in da Kindakrippn, oda kriag I jetzt endlich an gscheidn Schdaumpa?', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sind wir in der Kinderkrippe, oder krieg ich jetzt endlich ''nen g’scheiten Stamper?', '[{"kategorie": "wörtlich", "text": "\"Was soll ich mit dem Babyschluck? Kommt da jetzt bald ein Stamper für Erwachswene?\"  2. \"Das Schnapsgläschen ist ja für Säuglinge! Bring mir endlich einen richtigen Stamper mit Wumms drin!\"  3. \"Dieses Schnapsglas ist ja kleiner als mein Wille zur Abstinenz - schenk mir endlich ''nen richtigen Stamper ein!"}]'::jsonb, ''),
  ('schleich-di-sunst-faungsda-glei-an-schdaumpa-ei', 'Schleich di, sunst faungsda glei an Schdaumpa ei!', '', '', '', 'Wiener Gaunersprache', 'Schleich dich, sonst fängst du dir gleich einen Stamper ein!', '[{"kategorie": "wörtlich", "text": "\"Verzieh dich, sonst kriegst du gleich einen Schlag ab!\"  2. Hau ab, sonst gibt''s gleich ''nen Rempler in die Magengrube!  3. Mach die Biege, sonst landet mein Ellbogen gleich in deinen Rippen!"}]'::jsonb, ''),
  ('a-richtiga-drecksock-dea-hoizgschnitzde-kummd-von-hintn-und-haud-ma-an-rippnschdaumpa-eine-dass-i-mei-lungan-nimma-schbia', 'A richtiga Drecksock, dea Hoizgschnitzde - kummd von hintn und haud ma an Rippnschdaumpa eine, dass I mei Lungan nimma schbia!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ein richtiger Drecksack, dieser Holzg''schnitzte - kommt von hinten und haut mir einen Rippenstamper rein, dass ich meine Lunge nimmer spür!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Ein richtiger Drecksack, dieser Abwehrrecke - kommt von hinten und haut mir einen Hieb in die Rippen rein, dass ich meine Lunge nicht mehr spür''!\"   2. Ein echter Fiesling, dieser bullige Verteidiger – kommt von hinten und verpasst mir so einen Hieb in die Rippen, dass mir die Luft wegbleibt!  3. Ein mieser Hund, der Klotz – kommt von hinten und pflanzt mir so einen Rippencheck rein, dass ich kaum noch atmen kann!"}]'::jsonb, ''),
  ('den-miass-ma-schdampan-bevuara-uns-noo-de-butta-vom-brood-nimmd', 'Den miass ma schdampan, bevuara uns noo de Butta vom Brood nimmd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Den müssen wir stampern, bevor er uns noch die Butter vom Brot nimmt!', '[{"kategorie": "wörtlich", "text": "\"Den müssen wir jagen, sonst stiehlt er uns die Show!\"  2. Den müssen wir fortscheuchen, bevor er uns noch auf der Nase rumtanzt!\"  3. \"Den müssen wir loswerden, bevor er uns noch das Wasser abgräbt!\""}]'::jsonb, ''),
  ('sei-ex-lossd-si-ned-weggaschdampan-de-pickd-eam-wiara-kautschi-aum-schuach', 'Sei Ex lossd si ned weggaschdampan - de pickd eam wiara Kautschi aum Schuach!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seine Ex lässt sich nicht wegstampern - die pickt ihm wie ein Kautschi am Schuh!', '[{"kategorie": "wörtlich", "text": "\"Seine Ex lässt sich nicht wegjagen - die kleubt ihm wie ein Kaugummi am Schuh!\"  2. Seine Ex lässt sich nicht wegscdheuchen - die pickt wie Sekundenkleber an ihm!  3. Seine Ex ist wie ein Pop-up-Fenster – man klickt sie weg, und sie kommt immer wieder!"}]'::jsonb, ''),
  ('i-loss-mi-ned-so-aafoch-fuatschdampan-scho-goa-ned-von-so-an-pseudo-alpha-dea-mea-goeoe-ind-hoa-ois-hian-im-schaeaedl-hod', 'I loss mi ned so aafoch fuatschdampan - scho goa ned von so an Pseudo-Alpha, dea mea Göö ind Hoa ois Hian im Schäädl hod!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich lass mich nicht so einfach fortstampern - schon gar nicht von so einem Pseudo-Alpha, der mehr Gel in den Haaren als Hirn im Kopf hat!', '[{"kategorie": "wörtlich", "text": "\"Ich lass mich nicht so einfach wegscheuchen - erst recht nicht von so ''nem Selbstdarsteller!\" 2. Ich mach doch nicht den Abgang für so einen aufgeblasenen Gockel - wenn hier einer geht, dann sicher nicht ich!  3. Dieses Ego auf zwei Beinen kann mich nicht so einfach fortjagen - für so einen Möchtegern-Macho mach ich meinen Platz sicher nicht frei!"}]'::jsonb, ''),
  ('waunn-dea-amoi-aun-da-schaunk-schdeed-lossda-si-von-neamd-mea-haamschdampan-ned-amoi-vom-wiatn', 'Waunn dea amoi aun da Schaunk schdeed, lossda si von neamd mea haamschdampan - ned amoi vom Wiatn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der einmal an der Schank steht, lässt er sich von niemandem mehr heimstampern - nicht einmal vom Wirten!', '[{"kategorie": "wörtlich", "text": "\"Wenn der einmal an der Theke steht, kriegt ihn kein Schwein mehr dazu, heimzugehen – nicht mal der Wirt selbst!\"  2. Wenn der erst mal an der Schank pickt, bewegt ihn keiner mehr heim – nicht einmal der Wirt mit’m Besen!  3. Einmal festgewurzelt an der Schank, ist er nicht mehr heimzubekommen – höchstens mit’m Gabelstapler!"}]'::jsonb, ''),
  ('haam-gemma-no-laung-ned', 'Haam gemma no laung ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Heim gehen wir noch lange nicht!', '[{"kategorie": "wörtlich", "text": "\"An Heimgehen ist noch lange nicht zu denken!\"  2. Die Nacht ist noch jung - wir auch!  3. Wir bleiben, bis die Lichter ausgehen!"}]'::jsonb, ''),
  ('wea-fiad-mi-haam-allaa-find-i-nimma-zruck', 'Wea fiad mi haam? - Allaa find I nimma zruck!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wer führt mich heim? Allein find'' ich nimmer zurück!', '[{"kategorie": "wörtlich", "text": "\"Wer fährt mich mit dem Auto nach Hause? Allein finde ich nicht mehr zurück!\"  2. Wer fährt mich nach Hause? Ich find den Weg nicht mehr!  3. Könnte mich bitte jemand heimfahren - allein bin ich nicht mehr straßentauglich!"}]'::jsonb, ''),
  ('in-schuali-hauma-gestan-haamgfiad-sei-heaz-hod-vueue-z-frua-zum-schloong-aufghead', 'In Schuali hauma gestan haamgfiad - sei Heaz hod vüü z''frua zum Schloong aufghead!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Den Schurli haben wir gestern heimgeführt - sein Herz hat viel zu früh zu schlagen aufgehört!', '[{"kategorie": "wörtlich", "text": "\"Gestern haben wir den Schurli zur letzten Ruhe geleitet – sein Herz hörte viel zu früh auf zu schlagen!\"  2. Den Schurli haben wir gestern zur ewigen Ruhe geführt – still und traurig, weil sein Herz noch viel länger hätte schlagen sollen!  3. Schurlis Herz hat viel zu früh aufgehört zu schlagen – gestern haben wir ihn heimgeführt!"}]'::jsonb, ''),
  ('maunche-gaest-meakn-aafoch-ned-waunn-s-reicht-de-muassd-hoid-haamgeign', 'Maunche Gäst meakn aafoch ned, waunn''s reicht - de muassd hoid haamgeign!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Manche Gäste merken einfach nicht, wann''s reicht - die musst du halt heimgeigen!', '[{"kategorie": "wörtlich", "text": "\"Manche Gäste kapieren einfach nicht, wann es genug ist – die musst du halt nach Hause violinen!\"  [Zur Erklärung: Der Ausdruck bedeutete ursprünglich: jemanden ehrenvoll mit Musik nach Hause begleiten. Später dann wandelte sich die Bedeutung zu \"jemandem den Marsch blasen und wider seinen Willen hinauskomplimentieren\")"}, {"kategorie": "", "text": "Manchmal muss man Gästen helfen, den richtigen Moment zum Gehen zu finden - die werden dann halt mehr oder weniger sanft hinauskomplimentiert!  3. Manche Gäste checken es einfach nicht – denen muss man dann halt den Marsch blasen und  klarmachen: für euch ist Schluss, aus, vorbei!"}]'::jsonb, ''),
  ('den-hob-i-sowos-von-haamgeigd-dea-waass-jetzd-genau-wos-soche-is', 'Den hob I sowos von haamgeigd - dea waass jetzd genau, wos Soche is!', '', '', '', 'Wiener Gaunersprache', 'Den hab ich sowas von heimgegeigt - der weiß jetzt genau, was Sache ist!', '[{"kategorie": "wörtlich", "text": "\"Dem hab ich sowas von die Meinung gesagt - der weiß jetzt genau, was Sache ist!\"  2. Dem hab ich ordentlich den Kopf gewaschen – der weiß jetzt, wo der Hammer hängt!  3. Den hab ich so was von zurechtgestutzt – der sagt kein Wort mehr!  4. Dem hab ich ordentlich den Marsch geblasen – jetzt weiß er, woran er ist!"}]'::jsonb, ''),
  ('si-haampressn', 'si haampressn', '', '', '', 'Grundwortschatz Wienerisch', 'sich heimpressen', '[{"kategorie": "wörtlich", "text": "\"sich heimpressen\" (Kompositum aus dem Partikel [[heim]]=\"nach Hause\" und \"pressen\"=\"zwängen\")"}, {"kategorie": "scherzhaft für", "text": "\"sich schweren Herzens auf den Nachhauseweg machen\", sich wider Willen heimwärts begeben, \"sich aufraffen und heimrollen\", \"sich schweren Schrittes nach Hause schleppen\", [[haamroin]]"}]'::jsonb, 'Nooch ocht Gspritzde, a poa Schdampaln und zwaa Driiwaschdraara hob I mi haampressd - jeeda Määta a Kaumpf geengd Schweakroft!'),
  ('nooch-ocht-gspritzde-a-poa-schdampaln-und-zwaa-driiwaschdraara-hob-i-mi-haampressd-jeeda-maeaeta-a-kaumpf-geengd-schweakroft', 'Nooch ocht Gspritzde, a poa Schdampaln und zwaa Driiwaschdraara hob I mi haampressd - jeeda Määta a Kaumpf geengd Schweakroft!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach acht Gespritzten, ein paar Stamperln und zwei Drüberstreuern hab ich mich heimgepresst – jeder Meter ein Kampf gegen die Schwerkraft!', '[{"kategorie": "wörtlich", "text": "\"Nach acht Gläsern Spritzwein, ein paar Schnäpsen und zwei Absackern hab ich mich nach Hause geschleppt – jeder Meter ein Kampf gegen die Naturgesetze!\"  2. Nach acht Spritzern, fünf Schnapsraketen und zwei finalen Absackern hab ich mich auf den Nachhauseweg gemacht - jeder Schritt ein Ringen mit den Naturgesetzen und meinem Gleichgewichtssinn!  3. Berauscht von Spritzwein, Schnaps und Absackern, habe ich mich aufgerafft und auf auf den Heimweg begeben – jeder Schritt ein Kampf gegen die Schwerkraft!"}]'::jsonb, 'si haampressn'),
  ('kenntad-mi-wea-haamscheibm-und-ins-bett-leeng', 'Kenntad mi wea haamscheibm und ins Bett leeng?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Könnte mich wer heimschieben und ins Bett legen?', '[{"kategorie": "wörtlich", "text": "\"Könnte mich jemand nach Hause chauffieren und ins Bett legen?\"  2. Wär jemand so nett, mich heimzubringen und sanft im Bett zu versenken?  3. Kann mich bitte jemand heimfahren und direkt ins Bett einparken?"}]'::jsonb, ''),
  ('de-blonde-hod-mi-sowos-von-haamgleicht-bei-dea-brood-i-sicha-nimma', 'De Blonde hod mi sowos von haamgleicht - bei dea brood I sicha nimma!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Blonde hat mich sowas von heimgeleuchtet - bei der brate ich nimmer!', '[{"kategorie": "wörtlich", "text": "\"Die Blonde hat mir sowas von einer Abfuhr erteilt - die bagger'' ich sicher nicht mehr an!\"  2. Das Blondinchen hat mich gerade eiskalt abserviert – die mach ich sicher nicht mehr an!  3. Die Blonde hat mich so richtig abblitzen lassen - die rühre ich nie wieder an!"}]'::jsonb, ''),
  ('suach-uns-do-amoi-haam', 'Suach uns do amoi haam!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Such uns doch einmal heim!', '[{"kategorie": "wörtlich", "text": "\"Besuch uns doch einmal daheim!\" [Zur Erklärung: \"heimsuchen\" bedeutete ursprünglich: \"jemanden zu Hause besuchen\". Später dann wandelte sich die Bedeutung zu \"jemanden daheim in feindlicher Gesinnung besuchen\" bzw. zum heute gebräuchlichen \"heimsuchen\", das fast ausschließlich in der Bedeutung \"jemanden befallen\" bzw. \"über jemanden hereinbrechen\" verwendet wird. Mitunter gebraucht man im Wiener Dialekt aber noch heute das Wort \"heimsuchen\" in seiner ursprünglichen Bedeutung, nämlich \"jemandem einen Hausbesuch abstatten\")"}, {"kategorie": "", "text": "Statte uns doch mal ''nen Hausbesuch ab!  3. Komm uns doch mal zu Hause besuchen!"}]'::jsonb, ''),
  ('i-wea-jeedn-toog-von-meina-ex-haamgsuachd-de-is-wiara-fotzbloodan-deesd-nimma-los-wiast', 'I wea jeedn Toog von meina Ex haamgsuachd - de is wiara Fotzbloodan, deesd nimma los wiast!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich werde jeden Tag von meiner Ex heimgesucht - die ist wie ''ne Fotzblattern, die du nicht mehr los wirst!', '[{"kategorie": "wörtlich", "text": "\"Ich werde jeden Tag von meiner Ex heimgesucht - die kommt mir vor wie ''ne Fieberblase, die du nicht mehr los wirst!\"  2. Ich werd täglich von meiner Ex belästigt – die ist wie Herpes: bleibt, juckt, nervt!  3. Meine Ex überfällt mich jeden Tag wie ein Zombie - für mich tot, aber irgendwie immer noch da!"}]'::jsonb, ''),
  ('weinochtskeks-schdanzd-ma-ausn-taag-bevuas-aufs-bockblech-waundan', 'Weinochtskeks schdanzd ma ausn Taag, bevuas aufs Bockblech waundan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Weihnachtskekse stanzt man aus dem Teig, bevor sie auf das Backblech wandern!', '[{"kategorie": "wörtlich", "text": "\"Weihnachtskekse werden aus dem Teig ausgestochen, bevor sie auf das Backblech gelegt werden!\"  2. Die Kekse werden mit Förmchen aus dem Teig gedrückt, bevor man sie aufs Backblech legt!  3. Die Kekse werden mit viel Liebe aus dem Teig gestochen und dürfen dann in den Ofen!"}]'::jsonb, ''),
  ('i-hob-eam-glei-bei-da-tia-gschdanzd-no-bevuara-seavas-hod-soong-kenna', 'I hob eam glei bei da Tia gschdanzd, no bevuara ''Seavas'' hod soong kenna!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab ihn gleich bei der Tür gestanzt, noch bevor er ''Servus'' hat sagen können!', '[{"kategorie": "wörtlich", "text": "\"Ich hab ihn gleich an der Tür abserviert, noch bevor er ''Servus'' sagen konnte!\"  2. Ich hab ihn direkt an der Tür abblitzen lassen - er ist gar nicht zu Wort gekommen!  3. Ich hab ihn gleich vor der Tür geparkt, bevor er überhaupt was sagen konnte!"}]'::jsonb, ''),
  ('wos-haums-da-noo-ollas-gschdanzd', 'Wos haums da noo ollas gschdanzd?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Was haben sie dir noch alles gestanzt?', '[{"kategorie": "wörtlich", "text": "\"Was wurde dir noch alles gestrichen?\"  2. Was haben sie dir sonst noch alles aberkannt?  3. Was wurde dir sonst noch alles gekürzt?"}]'::jsonb, ''),
  ('mia-schdanzn-nix-wos-boizngsichad-is-nua-des-wos-noch-bitte-mitneema-schreit', 'Mia schdanzn nix, wos boizngsichad is - nua des, wos noch ''Bitte mitneema'' schreit!', '', '', '', 'Wiener Gaunersprache', 'Wir stanzen nichts, was bolzengesichert ist – nur das, was nach „Bitte mitnehmen“ schreit!', '[{"kategorie": "wörtlich", "text": "\"Wir stehlen nichts, was bolzengesichert ist – nur das, was nach „Bitte mitnehmen“ schreit!\"  2. Wir nehmen nichts mit Gewalt – nur das, was nicht angeschraubt ist!  3. Wir nehmen nichts, was ''ne Alarmanlage hat – nur das, was beleidigt wär, wenn man''s stehen lässt!"}]'::jsonb, ''),
  ('mia-haums-de-nummantofaen-gschdanzd', 'Mia haums de Nummantofän gschdanzd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir haben sie die Nummerntafeln gestanzt!', '[{"kategorie": "wörtlich", "text": "\"Mir wurden die Kennzeichentafeln gestohlen!\"  2. Jemand hat mir glatt das Autokennzeichen abgeschraubt!  3. Mir haben sie die Nummernschilder geklaut!"}]'::jsonb, ''),
  ('den-haums-gschdanzd', 'Den haums gschdanzd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Den haben sie gestanzt!', '[{"kategorie": "wörtlich", "text": "\"Den haben Sie gekündigt!\"  2. Der hat die Kündigung bekommen!  3. Der wurde gefeuert!  4. Den haben sie rausgeworfen!"}]'::jsonb, ''),
  ('dea-woidad-voifett-ind-disko-owa-da-tialschdeea-hod-eam-schoo-aum-eigaung-weggagschdanzd', 'Dea woidad voifett ind Disko - owa da Tialschdeea hod eam schoo aum Eigaung weggagschdanzd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der wollte vollfett in die Disco - aber der Türlsteher hat ihn schon am Eingang weggestanzt!', '[{"kategorie": "wörtlich", "text": "\"Der wollte hackedicht in den Club, aber der Türsteher hat ihn direkt am Eingang weggewiesen!\"  2. Der Typ war voll wie zehn Russen und wollte in die Disco - doch der Türsteher hat ihn schon am Eingang weggestampert!  3. Im Vollrausch wollte er in die Disco, kam aber nicht mal bis zum Seil – direkt vor''m Eingang hat ihn der Türsteher aus dem Verkehr gezogen!"}]'::jsonb, ''),
  ('i-hob-mei-ex-fuatgschdanzd-de-woa-schnoella-draussn-oisd-schaun-host-kenna', 'I hob mei Ex fuatgschdanzd - de woa schnölla draussn, oisd schaun host kenna!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich habe meine Ex fortgestanzt - die war schneller draußen, als du schauen hast können!', '[{"kategorie": "wörtlich", "text": "\"Ich hab meine Ex vor die Tür gesetzt - die war schneller draußen, als du schauen konntest!\"  2. Ich hab meine Ex rausgeschmissen – schneller, als sie „Wir müssen reden“ sag+C7878en konnte!  3. Ich hab meine Ex eiskalt rauskatapultiert – die war schneller weg, als du gucken konntest!"}]'::jsonb, ''),
  ('zua-schbeaschdund-ruafd-da-wiat-imma-in-schani-sei-oide-au-de-kummd-daunn-und-schdanzd-eam-min-beesn-haam', 'Zua Schbeaschdund ruafd da Wiat imma in Schani sei Oide au - de kummd daunn und schdanzd eam min Beesn haam!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zur Sperrstunde ruft der Wirt immer die Alte vom Schani an - die kommt dann und stanzt ihn mit dem Besen heim!', '[{"kategorie": "wörtlich", "text": "\"Zur Sperrstunde ruft der Wirt immer die Alte vom Johann an - kommt dann und scheucht ihn mit dem Besen wieder heim!\"  2. Wenn Zapfenstreich ist, telefoniert der Wirt immer mit Johanns Frau - die kehrt ihn dann höchstpersönlich aus dem Lokal, bevor er am Tresen einschläft!  3. Wenn Sperrstunde ist, kriegt der Schani immer Besuch von seiner besseren Hälfte – die jagt ihn dann mit dem Besen nach Hause!"}]'::jsonb, ''),
  ('si-fuatschdanzn', 'si fuatschdanzn', '', '', '', 'Grundwortschatz Wienerisch', 'sich fortstanzen', '[{"kategorie": "wörtlich", "text": "\"sich fortstanzen\" (Kompositum aus dem Partikel [[fort]]=\"weg\" und [[stanzen]]=\"entfernen\" [eigentlich: \"sich aus einem Ganzen entfernen\" - so wie es sonst die Stanzmaschine macht])"}, {"kategorie": "allg.", "text": "sich losreißen, sich eilig davonmachen, \"Reißaus nehmen\", \"sich vom Acker machen\", \"sich abnabeln\", \"sich abseilen\""}]'::jsonb, 'Ma soitad si fuatschdanzn, bevuas z''schbood is und du di noocha rechtfeatign muassd, warumsd iwahaupd noo do woasd!'),
  ('ma-soitad-si-fuatschdanzn-bevuas-z-schbood-is-und-du-di-noocha-rechtfeatign-muassd-warumsd-iwahaupd-noo-do-woasd', 'Ma soitad si fuatschdanzn, bevuas z''schbood is und du di noocha rechtfeatign muassd, warumsd iwahaupd noo do woasd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Man sollte sich fortstanzen, bevor es zu spät ist, und du dich nachher rechtfertigen musst, warum du überhaupt noch da warst!', '[{"kategorie": "wörtlich", "text": "\"Man sollte Reißaus nehmen, bevor es zu spät ist, und du dich nachher rechtfertigen musst, warum du überhaupt geblieben bist!\"  2. Seil dich ab, bevor es zu spät ist – sonst musst du nachher erklären, warum du überhaupt geblieben bist!  3. Es ist immer besser, sich früh vom Acker zu achen, als später begründen zu müssen, warum man nicht schon längst weg war!"}]'::jsonb, 'si fuatschdanzn'),
  ('da-wiat-schdampad-an-jeedn-aussi-dea-im-suff-sekant-oda-aulassich-wiad', 'Da Wiat schdampad an jeedn aussi, dea im Suff sekant oda aulassich wiad!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Wirt stampert jeden raus, der im Suff sekkant oder anlassig wird!', '[{"kategorie": "wörtlich", "text": "\"Der Wirt setzt jeden vor die Tür, der im Suff nervig oder zudringlich wird!\"  2. Wer im Rausch zu nervig oder zudringlich wird, fliegt beim Wirt hochkant raus!  3. Der Wirt schmeißt die Saufköpfe eigenhändig raus, wenn sie sich im Rausch nicht mehr im Griff haben!"}]'::jsonb, ''),
  ('rapid-hod-de-austria-easchd-in-da-valaengarung-aussigschdampad', 'Rapid hod de Austria easchd in da Valängarung aussigschdampad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Rapid hat die Austria erst in der Verlängerung rausgestampert!', '[{"kategorie": "wörtlich", "text": "\"Rapid hat die Austria erst in der Verlängerung aus dem Turnier gekickt!\"  2. Rapid hat die Austria erst in der Verlängerung aus dem Bewerb gekegelt!  3. Rapid hat das Cup-Aus für die Austria erst in der Verlängerung besiegelt!"}]'::jsonb, ''),
  ('gee-naus-bevuas-di-nausschdampan', 'Gee naus, bevuas di nausschdampan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Geh naus, bevor sie dich nausstampern!', '[{"kategorie": "wörtlich", "text": "\"Geh hinaus, bevor sie dich rausschmeißen!\"  2. Mach ''nen Abgang, noch ehe sie dich vor die Tür setzen!  3. Geh lieber von selber, bevor du ''nen Arschtritt kassierst!"}]'::jsonb, ''),
  ('waunn-da-bsoffane-aun-da-schaunk-ned-endlich-zum-singan-aufhead-schdampa-i-eam-eignhaendich-naus', 'Waunn da Bsoffane aun da Schaunk ned endlich zum Singan aufhead, schdampa I eam eignhändich naus!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der Besoffene an der Schank nicht endlich zu singen aufhört, stamper ich ihn eigenhändig naus!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Betrunkene an der Theke nicht endlich mit dem Gegröle aufhört, werf ich ihn eigenhändig raus!\"  2. Wenn der Rauschbruder an der Schank nicht bald still ist, setz ich ihn höchstpersönlich vor die Tür!  3. Wenn die grölende Rauschkugel an der Theke nicht sofort ruhig ist, schleif ich ihn eigenhändig zum Ausgang!"}]'::jsonb, ''),
  ('wea-wem-nausschdampad-wiss-ma-easchd-noochn-oeoefaschiassn', 'Wea wem nausschdampad, wiss ma easchd noochn Ööfaschiassn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wer wen rausstampert, wissen wir erst nach dem Elferschießen!', '[{"kategorie": "wörtlich", "text": "\"Wer wen aus dem Turnier befördert, wissen wir erst nach dem Elferschießen!\"  2. \"Wer fliegt und wer bleibt – das zeigt sich erst vom Punkt!\"  3. \"Wer wen aus dem Turnier kegelt, entscheidet sich erst im Elferschießen!\""}]'::jsonb, ''),
  ('kumm-fiar-in-opa-kuaz-naus-damita-a-wengl-frische-luft-ind-lungan-kriagd', 'Kumm, fiar in Opa kuaz naus, damita a wengl frische Luft ind Lungan kriagd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm, führ den Opa kurz raus, damit er ein wenig frische Luft in die Lungen kriegt!', '[{"kategorie": "wörtlich", "text": "\"Komm, führ den Opa kurz raus – ein bisschen Bewegung und frische Luft tun ihm sicher gut!\"  2. Komm, führ den Opa kurz raus, er könnte ein bisschen Sauerstoff vertragen!  3. Komm, führ den Opa ein bisschen an die frische Luft - ein kleiner Spaziergang würde ihm guttun!"}]'::jsonb, ''),
  ('ea-hods-aufs-laund-nausgfiad-und-noochn-piknik-glei-auf-da-wiisn-vanooschd', 'Ea hods aufs Laund nausgfiad und noochn Piknik glei auf da Wiisn vanooschd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hat sie aufs Land rausgeführt und nach dem Picknick gleich auf der Wiese vernascht!', '[{"kategorie": "wörtlich", "text": "\"Er hat sie raus ins Grüne gefahren und nach dem Picknick gleich auf der Wiese flachgelegt!\"  2. Er hat sie zum Picknickj aufs Land gelotst - und kaum war die Decke ausgebreitet, hat er sie auch schon vernascht!  3. Er hat sie raus ins Grüne gefahren und nach dem Picknick gleich auf der Wiese beglückt!"}]'::jsonb, ''),
  ('mia-haum-eam-heit-nausgfiad-schdueue-friidlich-und-oone-vueue-woate', 'Mia haum eam heit nausgfiad - schdüü, friidlich und oone vüü Woate!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wir haben ihn heute nausgeführt - still, friedlich und ohne viel Worte!', '[{"kategorie": "wörtlich", "text": "\"Wir haben ihn heute auf seinem letzten Weg geleitet - still, friedlich und ohne viele Worte!\"  2. \"Still und friedlich sind wir heute mit ihm den letzten Weg gegangen!\"  3. \"Wir haben ihm heute das letzte Geleit gegeben – still, friedlich und ohne viel Worte!\""}]'::jsonb, ''),
  ('i-bin-weggagaunga-von-eam-waeu-i-kaa-zweite-mama-schbueuen-wueue', 'I bin weggagaunga von eam, wäu I kaa zweite Mama schbüün wüü!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich bin von ihm weggegangen, weil ich keine zweite Mama spielen will!', '[{"kategorie": "wörtlich", "text": "\"Ich habe ihn verlassen, weil ich nicht länger seine Ersatz-Mama sein wollte!\"  2. Ich hab mich von ihm getrennt, weil ich jemanden will, der mitzieht – und nicht jemanden, den ich bemuttern muss!  3. Ich hab ihn verlassen, weil ich keinen Lebenspartner hatte, sondern einen schwer erziehbaren, kindischen Jungen!"}]'::jsonb, ''),
  ('de-scheiss-fotzbloodan-geed-aafoch-ned-wegga', 'De Scheiss-Fotzbloodan geed aafoch ned wegga!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Diese Scheiß-Fotzblattern geht einfach nicht weg!', '[{"kategorie": "wörtlich", "text": "\"Diese verdammte Fieberblase geht einfach nicht weg!\"  2. Dieser Scheiß-Herpes will einfach nicht verschwinden!  3. Diese Mist-Fieberblase heilt einfach nicht ab!"}]'::jsonb, ''),
  ('zeaschd-woid-ma-mitanaunda-weggafoan-owa-wiaris-gfroogd-hob-ob-oll-inkluusiv-aa-fia-sex-gueued-hods-schdoaniad', 'Zeaschd woid ma mitanaunda weggafoan - owa wiaris gfroogd hob, ob ''oll inkluusiv'' aa fia Sex güüd, hods schdoaniad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zuerst wollten wir miteinander wegfahren - aber wie ich sie gefragt hab, ob ''all inclusive'' auch für Sex gilt, hat sie storniert!', '[{"kategorie": "wörtlich", "text": "\"Zunächst wollten wir miteinander verreisen - aber wie ich sie gefragt hab, ob ''all inclusive'' auch für Sex gilt, hat sie storniert!\"  2. Eigentlich wollten wir gemeinsam in den Urlaub aufbrechen – aber als ich sie fragte, ob ''all inclusive'' auch Sex beinhaltet, hat sie postwendend abgesagt!  3. Geplant war Zweisamkeit unter Palmen – geworden is nichts aus der gemeinsamen Reise, weil ich das „Rundum-sorglos-Paket“ wohl falsch interpretiert hab!"}]'::jsonb, ''),
  ('de-oasch-bim-is-ma-schoo-wiida-vua-da-noosn-weggagfoan', 'De Oasch-Bim is ma schoo wiida vua da Noosn weggagfoan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Diese Arsch-Bim ist mir schon wieder vor der Nase weggefahren!', '[{"kategorie": "wörtlich", "text": "\"Diese verdammte Straßenbahn ist mir schon wieder vor der Nase weggefahren!\"  2. Ich renn, schwitz, fluch – und diese Scheiß-Tranway grinst mir mit den Rücklichtern ins Gesicht!  3. Die Bim und ich haben ne toxische Beziehung: Ich geb alles – aber sie fährt weg und lässt mich stehen!"}]'::jsonb, ''),
  ('kenntasd-in-mist-endlich-weggafian', 'Kenntasd in Mist endlich weggafian?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Könntest du den Mist endlich wegführen?', '[{"kategorie": "wörtlich", "text": "\"Könntest du den verdammten Mist endlich abtransportieren?\"  2. Wann gedenkst du, den Müll zur Deponie zu karren?  3. Kannst du den ganzen Krempel endlich abtransportieren und entsorgen?"}]'::jsonb, ''),
  ('wia-soi-i-do-weggaschaun-waunn-ma-dera-iare-zwaa-glockn-ins-gsicht-leitn', 'Wia soi I do weggaschaun, waunn ma dera iare zwaa Glockn ins Gsicht leitn?', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wie soll ich da wegschauen, wenn mir ihre zwei Glocken ins Gesicht läuten?', '[{"kategorie": "wörtlich", "text": "\"Wie soll ich da weggucken, wenn mir ihre zwei Hüpfburgen fast ins Gesicht springen?\"  2. Wie soll ich da nicht hinsehen, wenn ihre zwei Dinger fast aus dem Dekolleté hüpfen!  3. Wegsehen? - Wenn ihre zwei Glocken scheppern, ist das wie bei der Feuerwehr – da musst du hinschauen, ob du willst oder nicht!"}]'::jsonb, ''),
  ('i-muass-wegga-de-woeoed-brauchd-mi', 'I muass wegga - de Wööd brauchd mi!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich muss weg - die Welt braucht mich!', '[{"kategorie": "wörtlich", "text": "\"Ich muss los - die Welt braucht mich!\"  2. Die Plficht ruft - ich muss los!  3. Muss los und kurz die Welt retten!"}]'::jsonb, ''),
  ('mei-schlissl-is-wegga-hod-eam-viileichd-wea-gseeng', 'Mei Schlissl is wegga - hod eam viileichd wea gseeng?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein Schlüssel ist weg - hat ihn vielleicht wer gesehen?', '[{"kategorie": "wörtlich", "text": "\"Mein Schlüssel ist verschwunden – hat ihn zufällig jemand gesehen?\"  2. Ey, mein Schlüssel ist futsch – hat jemand ''ne Ahnung, wo der rumliegt?  3. Leute, mein Schlüssel ist irgendwie abhandengekommen - hat ihn vielleicht wer gesehen?"}]'::jsonb, ''),
  ('i-muass-wegga', 'I muass wegga!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich muss weg!', '[{"kategorie": "wörtlich", "text": "\"Ich muss los!\"  2. Ich muss gehen!  3. Ich muss fort!"}]'::jsonb, ''),
  ('raam-des-wegga', 'Raam des wegga!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Räum das weg!', '[{"kategorie": "wörtlich", "text": "\"Mach das weg!\"  2. \"Räum das fort!\"  3. \"Schaff das beiseite!\""}]'::jsonb, ''),
  ('seits-wegga-is-foeoeds-ma', 'Seits wegga is, fööds ma!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit sie weg ist, fehlt sie mir!', '[{"kategorie": "wörtlich", "text": "\"Seit sie fort ist, fehlt sie mir!\"  2. Seit sie nicht mehr da ist, sehne ich mich nach ihr!  3. Seit sie gegangen ist, vermisse ich sie schmerzlich!"}]'::jsonb, ''),
  ('wia-kumm-i-dazua-dass-i-eichare-brunzlackaln-aum-heisl-a-jeeds-moi-weggaputzn-muass', 'Wia kumm I dazua, dass I eichare Brunzlackaln aum Heisl a jeeds Moi weggaputzn muass?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie komme ich dazu, dass ich eure Brunzlackerln am Häusl ein jedes Mal wegputzen muss?', '[{"kategorie": "wörtlich", "text": "\"Wie komme ich dazu, eure Urinlachen am Klo immer wegputzen zu müssen?\"  2. Warum bin eigentlich immer ich diejenige, die eure Schweinereien im Klo wegwischen muss?  3. Ich bin doch nicht eure Putzfrau – wischt eure Urinpfützen am Klo doch selber auf!"}]'::jsonb, ''),
  ('in-zwetschgnfleck-von-da-oma-haum-de-gschroppn-in-drei-minuutn-weggaputzd-ghobd', 'In Zwetschgnfleck von da Oma haum de Gschroppn in drei Minuutn weggaputzd ghobd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Den Zwetschkenfleck von der Oma haben die Gschropp''n in drei Minuten weggeputzt gehabt!', '[{"kategorie": "wörtlich", "text": "\"Die Kinder haben Omas Pflaumenblechkuchen in drei Minuten aufgegessen!\"  2. Omas Zwetschkenfleck hat nicht lang überlebt – die Kinder haben sich draufgestürzt wie die Heuschrecken!  3. Omas Blechkuchen war in Windeseile verschwunden – den haben die Kinder weggefuttert, noch bevor er kalt war!"}]'::jsonb, ''),
  ('wea-uns-bei-da-haeae-vapfeifd-wiad-weggaputzd-gaunz-aafoch', 'Wea uns bei da Hää vapfeifd, wiad weggaputzd - gaunz aafoch!', '', '', '', 'Wiener Gaunersprache', 'Wer uns bei der Höh verpfeift, wird weggeputzt - ganz einfach!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Wer uns bei der Polizei verpfeift, wird weggeputzt - ganz einfach!\"  2. Wer singt, wird ausgeknipst - für immer!  3. Wer uns bei der Polizei ans Messer liefert, wird kaltgestellt – sauber und leise!"}]'::jsonb, ''),
  ('heit-putz-ma-eich-wegga-bis-nimma-wissds-wo-oobm-und-untn-is', 'Heit putz ma eich wegga - bis nimma wissds, wo oobm und untn is!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Heute putzen wir euch weg - bis ihr nimmer wisst, wo oben und unten ist!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Heute fegen wir euch vom Platz - bis ihr nicht mehr wisst, wo oben und unten ist!\"  2. Heut machen wir euch nass, bis ihr nicht mehr wisst, wo der Waschraum ist!  3. Heute klopfen wir euch vom Platz, dass euch selbst der Platzwart nicht mehr wiedererkennen wird!"}]'::jsonb, ''),
  ('soboida-wos-siasses-siichd-wiads-vanooschd-egal-ob-zuckal-oda-zuckapuppal', 'Soboida wos Siasses siichd, wiads vanooschd - egal ob Zuckal oda Zuckapuppal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sobald er was Süßes sieht, wird''s vernascht - egal ob Zuckerl oder Zuckerpupperl!', '[{"kategorie": "wörtlich", "text": "\"Kaum sieht er was Süßes, wird''s vernascht – egal ob Bonbon oder Blondine!\"  2. Was süß ist, wird von ihm postwendend vernascht – ganz gleich ob aus der Bonbonpackung oder mit High Heels!  3. Süßes ist bei ihm nicht sicher – ob aus der Dose oder mit Lippenstift!"}]'::jsonb, ''),
  ('im-aans-geeng-aans-vanooschda-an-jeedn', 'Im Aans geeng Aans vanooschda an jeedn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'im Eins gegen Eins vernascht er einen jeden!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Im Eins-gegen-Eins lässt er jeden stehen!\"  2. Wenn''s Mann gegen Mann geht, spielt er jeden schwindlig!  3. Im Duell Mann gegen Mann wickelt er jeden Gegner ein wie ein Pausenbrot!"}]'::jsonb, ''),
  ('de-san-a-jausngeegna-de-vanoosch-ma-zum-fruaschduck', 'De san a Jausngeegna - de vanoosch ma zum Fruaschduck!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die sind ein Jausengegner - die vernaschen wir zum Frühstück!', '[{"kategorie": "wörtlich", "text": "\"Die sind bestenfalls ein Appetithäppchen für uns - die vernaschen wir zum Frühstück!\"  2. Das wird ein Spaziergang - mit denen machen wir kurzen Prozess!  3. Die sind für uns Kanonenfutter – die putzen wir im Vorbeigehen weg!"}]'::jsonb, ''),
  ('i-hob-eam-zsaummgschdampad-dass-eam-hean-und-seeng-vagaungan-is-iagendwaunn-reichds-hoid', 'I hob eam zsaummgschdampad, dass eam Hean und Seeng vagaungan is - iagendwaunn reichds hoid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab ihn zusammengestampert, dass ihm Hören und Sehen vergangen ist – irgendwann reicht’s halt!', '[{"kategorie": "wörtlich", "text": "\"Ich hab ihn zusammengestaucht, dass ihm Hören und Sehen vergangen ist – irgendwann ist''s halt genug!\"  2. Ich hab ihn verbal dermaßen abgewatscht, dass er gar nimmer wusste, wo oben und unten ist - irgendwann ist das Maß halt voll!  3. Ich hab ihn derart zur Schnecke gemacht, dass ihm die Ohren gewackelt haben – aber irgendwann ist halt Schluss mit lustig!"}]'::jsonb, ''),
  ('si-zsaummschdampan', 'si zsaummschdampan', '', '', '', 'Grundwortschatz Wienerisch', 'sich zusammenstampern', '[{"kategorie": "wörtlich", "text": "\"sich zusammenstampern\" (Kompositum aus dem Partikel \"zusammen\"=\"zu einem Ganzen\" und \"stampern\"=\"herrichten\")"}, {"kategorie": "scherzhaft für", "text": "\"sich zusammenzimmern\", sich zurechtmachen, sich aufbrezeln, sich aufdonnern, sich herausputzen, sich schönmachen, [[sich]] aufmascherln"}]'::jsonb, 'De hod si wiida zsaummgschdampad wia fian Oopanboi - dabei geeds nua um a Packl Tschik ind Trafik!'),
  ('de-hod-si-wiida-zsaummgschdampad-wia-fian-oopanboi-dabei-geeds-nua-um-a-packl-tschik-ind-trafik', 'De hod si wiida zsaummgschdampad wia fian Oopanboi - dabei geeds nua um a Packl Tschik ind Trafik!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die hat sich wieder zusammgestampert wie für den Opernball – dabei geht sie nur um ein Packl Tschick nur in die Trafik!', '[{"kategorie": "wörtlich", "text": "\"Die hat sich wieder aufgebrezelt wie für den Opernball – dabei geht sie nur in die Trafik Zigaretten holen!\"  2. Die hat sich wieder aufgeputzt, als ging''s auf’n roten Teppich – dabei geht sie nur in die Trafik um ein packerl Zigaretten!  3. Die hat sich wieder aufgedonnert, als ginge sie ins Burgtheater – dabei holt sie vom [[wamperten]] Trafikanten nur ''ne Schachtel Zigaretten!"}]'::jsonb, 'si zsaummschdampan'),
  ('fuat-mid-eam', 'Fuat mid eam!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Weg mit ihm!', '[{"kategorie": "wörtlich", "text": "\"Weg mit ihm!\"  2. Schmeißt ihn raus!  3. Ab mit ihm!  4. Jagt ihn zum Teufel!"}]'::jsonb, ''),
  ('seits-fuat-is-foeoeds-ma', 'Seits fuat is, fööds ma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seit sie fort ist, fehlt sie mir!', '[{"kategorie": "wörtlich", "text": "\"Seit sie weg ist, fehlt sie mir!\"  2. Seit sie nicht mehr da ist, sehne ich mich nach ihr!  3. Seit sie gegangen ist, vermisse ich sie schmerzlich!"}]'::jsonb, ''),
  ('in-aan-fuat', 'in aan fuat', '', '', '', 'Wiener Sprüche, die sitzen!', 'in einem fort', '[{"kategorie": "wörtlich", "text": "\"ohne Unterlass\""}, {"kategorie": "", "text": "\"ohne Pause\""}, {"kategorie": "", "text": "[[in aana Tua]]"}]'::jsonb, 'Dea reedt in an fuat auf mi ei - ois häd I sunst nix z''tuan!'),
  ('dea-reedt-in-an-fuat-auf-mi-ei-ois-haed-i-sunst-nix-z-tuan', 'Dea reedt in an fuat auf mi ei - ois häd I sunst nix z''tuan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der redet in einem fort auf mich ein - alt hätte ich sonst nichts zu tun!', '[{"kategorie": "wörtlich", "text": "\"Der redet ununterbrochen auf mich ein – als hätt'' ich sonst nichts zu tun!\"  2. Der bombardiert mich pausenlos mit seinem Gequatsche – als hätte ich sonst kein Leben!  3. Der quatscht mir unentwegt die Ohren voll - als ob ich nur Zeit für ihn hätte!"}]'::jsonb, 'in aan fuat'),
  ('wiafs-oide-zeig-fuat', 'Wiafs oide Zeig fuat!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Wirf das alte Zeug fort!', '[{"kategorie": "wörtlich", "text": "\"Schmeiß das alte Zeug weg!\"  2. Muster die alten Sachen aus!  3. Wirf den alten [[Krempel]] weg!"}]'::jsonb, ''),
  ('fuatwuaschdln-is-ka-loesung-waunns-mid-jeedn-toog-nua-noo-schlimma-wiad', 'Fuatwuaschdln is ka Lösung, waunns mid jeedn Toog nua noo schlimma wiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Fortwursteln ist keine Lösung, wenn es mit jedem Tag nur noch schlimmer wird!', '[{"kategorie": "wörtlich", "text": "\"Weitermurksen ist keine Lösung, wenn sich die Lage von Tag zu Tag nur noch weiter verschlechtert!\"  2. Im alten Trott weiterzumachen, obwohl die Lage immer schlimmer wird, ist auch keine Lösung!  3. Weiterwursteln ist keine Lösung, wenn man längst weiß, dass der Karren schon im Dreck steckt!"}]'::jsonb, ''),
  ('i-bin-kaa-mochatschek-i-bin-a-fuatwuaschdla-owa-iagendwia-schlog-i-mi-aa-duachs-leebm', 'I bin kaa Mochatschek, I bin a Fuatwuaschdla - owa iagendwia schlog I mi aa duachs Leebm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin kein Machatschek, ich bin ein Fortwurstler - aber irgendwie schlag'' ich mich auch durchs Leben!', '[{"kategorie": "wörtlich", "text": "\"Ich bin kein Macher, eher ein Durchwurstler – aber irgendwie schlage ich mich auch durchs Leben, Tag für Tag!\"  2. Ich bin kein Macher, ich bin ein Durchschlürfer – ich bin der, der immer weiterwurstelt, auch wenn nichts weitergeht!  3. Als Durchwurstler mache ich keine großen Sprünge, sondern schlürfe nur so durch – aber vorwärts geht''s trotzdem!"}]'::jsonb, ''),
  ('si-fuatwuaschdln', 'si fuatwuaschdln', '', '', '', 'Grundwortschatz Wienerisch', 'sich fortwursteln', '[{"kategorie": "wörtlich", "text": "\"sich fortwursteln\" (Kompositum aus dem Partikel [[fort]]=\"weiter\" und \"wursteln\"=\"murksen\")"}, {"kategorie": "allg.", "text": "\"sich durchwursteln\", \"sich durchschlagen\", \"sich durchlavieren\", \"sich fortmühen\""}]'::jsonb, 'Mei Leebmsplan? Mi fuatwuaschdln von an Toog zum nächstn!'),
  ('mei-leebmsplan-mi-fuatwuaschdln-von-an-toog-zum-naechstn', 'Mei Leebmsplan? Mi fuatwuaschdln von an Toog zum nächstn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Lebensplan? Mich fortwursteln von einem Tag zum nächsten!', '[{"kategorie": "wörtlich", "text": "\"Mein Lebensentwurf? Mich von einem Tag zum nächsten [[hangeln]]!\"  2. Mein Lebenskonzept: Immer schön weiterwurschteln!  3. Großer Plan? Keiner. Ich murks mich halt von Tag zu Tag irgendwie durchs Leben!"}]'::jsonb, 'si fuatwuaschdln'),
  ('gee-ned-fuat-des-beste-kummd-easchd', 'Gee ned fuat - des Beste kummd easchd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Geh nicht fort - das Beste kommt erst!', '[{"kategorie": "wörtlich", "text": "\"Warte, du kannst jetzt echt nicht gehen – das Highlight kommt ja erst!\"  2. Nicht gehen - jetzt wird’s erst richtig gut!  3. Verlass uns nicht – das Beste kommt nämlich erst am am Schluss!"}]'::jsonb, ''),
  ('geesd-mit-mia-fuat', 'Geesd mit mia fuat?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Gehst du mit mir fort?', '[{"kategorie": "wörtlich", "text": "\"Gehst du mit mir aus?\"  2. Hättest du Lust, mit mir auszugehen?  3. Lust auf einen gemeinsamen Abend?"}]'::jsonb, ''),
  ('weng-meina-kaunnst-ruhig-fuatgee', 'Weng meina kaunnst ruhig fuatgee!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Wegen meiner kannst du ruhig fortgehen!', '[{"kategorie": "wörtlich", "text": "\"Meinetwegen kannst du ruhig alleine außer Haus gehen!\"  2. Von mir aus kannst du gerne alleine losgehen - ist kein Problem!  3. Wenn es nach mir geht, kannst du ruhig alleine ausgehen - ich hab damit kein Problem!"}]'::jsonb, 'weng meina'),
  ('fuatfoan-is-heia-ned-drin', 'Fuatfoan is heia ned drin!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fortfahren ist heuer nicht drin!', '[{"kategorie": "wörtlich", "text": "\"Fortfahren fällt heuer aus!\"  2. \"An Urlaub ist heuer nicht zu denken!\"  3. Ferienmachen ist dieses Jahr nicht leistbar!  4. Dieses Jahr gibt’s Balkonien statt Bali!"}]'::jsonb, ''),
  ('i-kumm-von-do-ned-fuat', 'I kumm von do ned fuat!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich komm von da nicht fort!', '[{"kategorie": "wörtlich", "text": "\"Ich komme nicht weg von hier!\"  2. Ich kann mich hier nicht loseisen!  3. Ich hänge hier fest!  4. Ich bin hier gefangen wie ein Fisch im Netz!"}]'::jsonb, ''),
  ('a-fuatkumman-in-da-hockn-is-kaa-zuckaschleckn-do-muassd-de-oeoeboong-ausfoan-sunst-bleibsd-auf-da-schdreckn', 'A Fuatkumman in da Hockn is kaa Zuckaschleckn - do muassd de Ööboong ausfoan, sunst bleibsd auf da Schdreckn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ein Fortkommen in der Hacken ist kein Zuckerschlecken - da musst du die Ellbogen ausfahren, sonst bleibst du auf der Strecke!', '[{"kategorie": "wörtlich", "text": "\"Ein Fortkommen im Job ist kein Honiglecken  – da musst du dich durchboxen, sonst wirst du überrollt!\"  2. Ein Weiterkommen im Job ist harte Kost – wer nicht schiebt, wird geschoben!  3. Ein Fortkommen im Beruf ist kein Spaziergang – da musst du zubeißen, sonst fressen sie dich auf!"}]'::jsonb, ''),
  ('renn-ma-ned-fuat', 'Renn ma ned fuat!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Renn mir nicht fort!', '[{"kategorie": "wörtlich", "text": "\"Lauf mir nicht davon!\"  2. Lass mich hier nicht alleine stehen!  3. Hau mir nur ja nicht ab!"}]'::jsonb, ''),
  ('schoff-in-mist-fuat-von-do', 'Schoff in Mist fuat von do!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Schaffe den Mist fort von da!', '[{"kategorie": "wörtlich", "text": "\"Mach den Mist weg von da!\"  2. Räum den Müll hier weg!  3. Schaff den Unrat weg von da!"}]'::jsonb, ''),
  ('da-schuali-hod-jetzd-lokalvabood-waeura-de-laeaean-schdampaln-imma-geeng-d-waund-pfeffad-hod', 'Da Schuali hod jetzd Lokalvabood - wäura de lääan Schdampaln imma geeng d''Waund pfeffad hod!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Schurli hat jetzt Lokalverbot - weil er die leeren Stamperln immer gegen die Wand gepfeffert hat!', '[{"kategorie": "wörtlich", "text": "\"Dem Schurli haben’s jetzt ein Hausverbot verpasst – weil er ständig die leeren Schnapsgläser immer gegen die Wand geworfen hat!\"  2. Der Schurli darf nimmer ins Beisl – weil er die leeren Stamperln immer Richtung Wand gepfeffert hat!  3. Der Schurli ist gesperrt – der Depp hat jedes Stamperl nach’m Trinken gegen die Mauer gedonnert!"}]'::jsonb, ''),
  ('a-schdampal-aum-moang-vatreibd-kumma-und-soang', 'A Schdampal aum Moang vatreibd Kumma und Soang!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Stamperl am Morgen vertreibt Kummer und Sorgen!', '[{"kategorie": "wörtlich", "text": "\"Ein kleiner Schnaps zur Morgenstund – macht Herz und Seele wieder g''sund!\"  2. Mit einem Stamperl zum Frühstück sieht die Welt gleich freundlicher aus!  3. Ein Stamperl am Morgen – weg sind die Sorgen, hin ist der Frust – und kommt wieder Lust!"}]'::jsonb, ''),
  ('a-schdampal-ins-kreiz-und-kusch-bist', 'A Schdampal ins Kreiz, und kusch bist!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Stamperl ins Kreuz - und kusch bist!', '[{"kategorie": "wörtlich", "text": "\"Ein kurzer Ellbogenstoß in den Rücken - und du hast Funkstille!\"  2. Kriegst du von mir ''nen kleinen Rempler ins Kreuz, dann hältst du sofort die Klappe!  3. Ein sauberer Ellbogenstoß ins Kreuz - und du hältst die Papp''n!"}]'::jsonb, ''),
  ('a-klaana-schnops-zua-moagnschdund-mochd-heaz-und-soeoe-glei-wiida-gsund', 'A klaana Schnops zua Moagnschdund mochd Heaz und Söö glei wiida gsund!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein kleiner Schnaps zur Morgenstund macht Herz und Seele wieder g''sund!', '[{"kategorie": "wörttlich", "text": "\"Ein Stamperl am Morgen vertreibt Kummer und Sorgen!\"   2. Mit einem Schnapserl zum Frühstück sieht die Welt gleich freundlicher aus!  3. Ein Stamperl am Morgen – weg sind die Sorgen, hin ist der Frust – und kommt wieder Lust!"}]'::jsonb, ''),
  ('an-wei-deaf-ma-ned-saufn-den-muass-ma-bippaln', 'An Wei deaf ma ned saufn - den muass ma bippaln!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Einen Wein darf man nicht saufen - den muss man biberln!', '[{"kategorie": "wörtlich", "text": "\"Wein säuft man nicht - man genießt ihn in kleinen Schlucken!\"  2. Wein wird nicht gesoffen, sondern Schluck für Schlöuck genossen!  3. Ein echter Weinfreund biberlt – ein Banause säuft!"}]'::jsonb, 'an Wei bippaln'),
  ('dea-bippald-jeedn-toog-seine-zeen-gschbritzdn-de-brauchda-hoid-daunn-geeds-eam-guad', 'Dea bippald jeedn Toog seine zeen Gschbritzdn - de brauchda hoid, daunn geeds eam guad!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der biberlt jeden Tag seine zehn G''spritzten - die braucht er halt, dann geht''s ihm gut!', '[{"kategorie": "wörtlich", "text": "\"Der zieht sich täglich seine zehn G’spritzten rein – die braucht er halt, dann geht''s ihm gut!\"  2. Seine zehn Spritzer sind sein tägliches Pflichtprogramm – sonst wird er grantig und unrund!  3. Der knallt sich jeden Tag zehn Spritzer - dann bleibt er in der Spur!"}]'::jsonb, 'an Wei bippaln'),
  ('an-wei-bippaln', 'an Wei bippaln', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'einen Wein bipperln', '[{"kategorie": "wörtlich", "text": "\"einen Wein biberln\"  (vom lateinischen \"bibere\"=\"trinken\")"}, {"kategorie": "allg.", "text": "Wein genussvoll trinken, süffeln, Schluck für Schluck genießen, nippend trinken, in kleinen Schlucken trinken, [[zipfeln]]"}, {"kategorie": "scherzhaft für", "text": "\"Wein gern und regelmäßig trinken\", [[bechern]], [[tschechern]], [[trankeln]]"}]'::jsonb, ''),
  ('reis-brauchd-vueue-wossa-vua-oim-aum-aufaung-waunna-keimd-und-de-reispflaunzn-schaud-aus-wiara-laungs-groos-mit-klaana-keandln-drau', 'Reis brauchd vüü Wossa, vua oim aum Aufaung, waunna keimd - und de Reispflaunzn schaud aus wiara laungs Groos mit klaana Keandln drau!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Reis braucht viel Wasser, vor allem am Anfang, wenn er keimt - und die Reispflanze schaut aus wie langes Gras mit kleinen Körnern dran!', '[{"kategorie": "wörtlich", "text": "\"Reis braucht ziemlich viel Wasser, vor allem am Anfang, wenn er anfängt zu wachsen – und die Pflanze sieht aus wie hohes Gras mit Körnern obendrauf!\"  2. Damit Reis gut wächst, braucht er am Anfang richtig viel Wasser – und die Pflanze erinnert ein bisschen an langes Gras mit kleinen Körnern dran!  3. Reis wächst am besten mit viel Wasser, besonders wenn er gerade keimt – und sieht aus wie Gras, nur mit kleinen Körnchen dran!"}]'::jsonb, ''),
  ('reis-is-de-peafekte-beiloog-zu-an-broodhendl-an-natuaschnitzl-ooda-an-koibsbroodn', 'Reis is de peafekte Beiloog zu an Broodhendl, an Natuaschnitzl ooda an Koibsbroodn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Reis ist die perfekte Beilage zu einem Brathendl, einem Naturschnitzel oder einem Kalbsbraten!', '[{"kategorie": "wörtlich", "text": "\"Zu Brathuhn, Naturschnitzel oder Kalbsbraten ist Reis die perfekte Beilage!\"  2. Reis eignet sich ideal als Beilage zu Brathendl, Naturschnitzel oder Kalbsbraten!  3. Ob Brathendl, Schnitzel oder Kalbsbraten – mit Reis als Beilage wird’s ein Hochgenuss!"}]'::jsonb, ''),
  ('reis-schdraan', 'Reis schdraan', '', '', '', 'Wiener Sprüche, die sitzen!', 'Reis streuen', '[{"kategorie": "wörtlich", "text": "\"Reis streuen\" (wobei [[Reis]] in dieser Redewendung verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert)"}, {"kategorie": "dialektal, Kotmetapher", "text": "\"Kot in Kugelform streuen\" (=\"sich anscheißen vor lauter Angst\")"}, {"kategorie": "fig.", "text": "eine Scheißangst haben"}, {"kategorie": "", "text": "vor Angst in die Hose machen"}, {"kategorie": "", "text": "\"die Muffe sausen lassen\""}, {"kategorie": "", "text": "\"Muffensausen bekommen\""}]'::jsonb, 'Bschissaln, de Reis schdraan, waunn de Hää auruckd, kaunnsd beim Eidiiwän ned brauchn!'),
  ('bschissaln-de-reis-schdraan-waunn-de-haeae-auruckd-kaunnsd-beim-eidiiwaen-ned-brauchn', 'Bschissaln, de Reis schdraan, waunn de Hää auruckd, kaunnsd beim Eidiiwän ned brauchn!', '', '', '', 'Wiener Gaunersprache', 'Bschisserln, die Reis streuen, wenn die Höh anrückt, kannst du beim Eindippeln nicht brauchen!', '[{"kategorie": "wörtlich", "text": "\"Schisser, die sich in die Hose machen, wenn die Polizei anrückt, kannst du beim Einbrechen nicht brauchen!\"  2. Schlotterer, die gleich Muffensausen kriegen, wenn die Bullen aufkreuzen, kannst du bei ''ner Nachtschicht nicht gebrauchen!  3. Feiglinge, die sich in die Hose machen, sobald’s Blaulicht flackert, kannst du beim Einbrechengehen vergessen!"}]'::jsonb, 'Reis schdraan'),
  ('in-reis-kriang', 'in Reis kriang', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Reis kriegen', '[{"kategorie": "wörtlich", "text": "\"den Reis bekommen\" (wobei [[Reis]] in dieser Redewendung verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert)"}, {"kategorie": "", "text": "\"Angst bekommen\" (\"sich vor Angst in die Hose scheißen\")"}, {"kategorie": "", "text": "\"Muffensausen bekommen\""}, {"kategorie": "", "text": "\"in Panik geraten\""}, {"kategorie": "", "text": "[[Gamaschn kriang]]"}]'::jsonb, 'Da Koarl hod in Reis kriagd und is ooboschd!'),
  ('du-bist-da-gressde-reisgaenga-unta-da-sunn-du-ziidasd-jo-schoo-waunn-da-wind-pfeifd', 'Du bist da gressde Reisgänga unta da Sunn - du ziidasd jo schoo, waunn da Wind pfeifd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Du bist der größte Reisgänger unter der Sonne - du zitterst ja schon, wenn der Wind pfeift!', '[{"kategorie": "wörtlich", "text": "\"Du bist doch der größte Angsthase unter der Sonne – zitterst ja schon, wenn der Wind pfeift!\"  2. Du bist doch der Ober-Hosenscheißer – brauchst ''ne Windel, wenn nur ein bisschen der Wind pfeift!  3. Du bist der ärgste Schlappschwanz, der mir jemals untergekommen ist - du scheißt ja schon in die Hose, wenn der Wind pfeift!"}]'::jsonb, ''),
  ('ziag-dar-a-windl-au-du-reisschdraara-damitsd-uns-ned-de-buude-vasaust-waunnsd-vua-lauta-aungst-ind-hoosn-scheissd', 'Ziag dar a Windl au, du Reisschdraara - damitsd uns ned de Buude vasaust, waunnsd vua lauta Aungst ind Hoosn scheissd!', '', '', '', 'Wiener Gaunersprache', 'Zieh dir ’ne Windel an, du Reisstreuer - damit du uns nicht die Bude versaust, wenn du vor lauter Angst in die Hose scheißt!', '[{"kategorie": "wörtlich", "text": "\"Zieh dir ’ne Windel an, du Schisser - damit du uns nicht die Bude versaust, wenn du dir vor lauter Angst in die Hose kackst!\"  2. Schnall dir lieber ''ne Pampers um, du Hosenscheißer – sonst stinkst du uns beim Bruch die ganze Hütte voll, wenn dir wieder die Muffe geht!  3. Pack dir ''ne Windel ein, du Flatterarsch – bevor du vor lauter Angst wieder in die Buchse scheißt und uns die Bude versaust!"}]'::jsonb, ''),
  ('da-reis-deaf-da-ned-gee', 'Da Reis deaf da ned gee!', '', '', '', 'Wiener Gaunersprache', 'Der Reis darf dir nicht gehen!', '[{"kategorie": "wörtlich", "text": "\"Scheiß dir bloß nicht in die Hose!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "Jetzt darf dir nicht die Düse gehen!  3. Bloß keinen Flattermann kriegen!  4. Nicht einknicken, klar?  5. Angst darfst du keine haben!"}]'::jsonb, ''),
  ('wem-geed-da-reis', 'wem geed da Reis', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem geht der Reis', '[{"kategorie": "wörtlich", "text": "\"jemand scheißt sich vor Angst in die Hose\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "\"jemandem geht die Düse\""}, {"kategorie": "", "text": "\"jemand kriegt den Flattermann\""}, {"kategorie": "", "text": "\"jemand kriegt Muffensausen\""}]'::jsonb, 'An Eidiiwla deaf ned da Reis gee, waunn da Alarm auschloogd!'),
  ('an-eidiiwla-deaf-ned-da-reis-gee-waunn-da-alarm-auschloogd', 'An Eidiiwla deaf ned da Reis gee, waunn da Alarm auschloogd!', '', '', '', 'Wiener Gaunersprache', 'Einem Eindübler darf nicht der Reis gehen, wenn der Alarm anschlägt!', '[{"kategorie": "wörtlich", "text": "\"Einem Einbrecher darf nicht die Düse gehen, wenn der Alarm anschlägt!\"  2. Beim Bruch darf dir nicht die Muffe sausen, wenn der Alarm losheult!  3. Ein Profi-Einbrecher scheißt nicht gleich in die Hose, wenn die Sirene losröhrt – da bleibt man eiskalt!"}]'::jsonb, 'wem geed da Reis'),
  ('scheiss-mit-reis', 'Scheiss mit Reis!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Scheiß mit Reis!', '[{"kategorie": "wörtlich, Fluch", "text": "\"Verdammte Scheiße!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "\"Kack mit Lack!\"  3. \"Heilige Scheiße!\"  4. \"Ach du Scheiße!\""}]'::jsonb, 'Scheiss mit Reis is aara Schbeis!'),
  ('scheiss-mit-reis-is-aara-schbeis', 'Scheiss mit Reis is aara Schbeis!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Scheiß mit Reis ist auch ''ne Speis!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Lieber schlecht gegessen als hungrig!\"  2. \"Mist mit Brot geht auch zur Not!\"  3. \"Friss oder stirb - besser als nichts!\""}]'::jsonb, ''),
  ('kack-mit-lack', 'Kack mit Lack!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Kack mit Lack!', '[{"kategorie": "wörtlich, Fluch", "text": "\"Scheiß mit Reis!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "\"Verdammte Scheiße!\"  3. \"Heilige Scheiße!\"  4. \"Ach du Scheiße!\""}]'::jsonb, ''),
  ('dea-hod-vua-lauta-aungst-an-reis-gschissn', 'Dea hod vua lauta Aungst an Reis gschissn!', '', '', '', 'Wiener Gaunersprache', 'Der hat vor lauter Angst ''nen Reis geschissen!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich vor lauter Angst in die Hose geschissen!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "Dem ist vor lauter Angst der Arsch explodiert!  3. Der hat''s vor lauter Angst laufen lassen und sich die Hosen vollgeschissen!"}]'::jsonb, ''),
  ('mia-geed-da-reis', 'Mia geed da Reis!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mir geht der Reis!', '[{"kategorie": "wörtlich", "text": "\"Ich habe eine Scheißangst!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "Ich mache mir vor Angst in die Hose !  3. Mir geht die [[Muffn]]!"}]'::jsonb, ''),
  ('mia-geed-uandlich-da-reis', 'Mia geed uandlich da Reis!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir geht ordentlich der Reis!', '[{"kategorie": "wörtlich", "text": "\"Ich habe eine richtige Scheißangst!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "Ich mach vor lauter Angst in die Hose!  3. Mir geht ordentlich die [[Muffn]]!"}]'::jsonb, ''),
  ('i-hob-in-reis-in-kuugaln-gleegd', 'I hob in Reis in Kuugaln gleegd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab den Reis in Kugerln gelegt!', '[{"kategorie": "wörtlich", "text": "\"Ich hab mir vor Angst in die Hose geschissen - bömmerlweise!\" (wobei [[Reis]] in diesem Fall verhüllend für den kugelförmigen Kot [[[Bömmerl]]] von Hasen, Ziegen bzw. Rehen steht, der an die Form von Reiskörnern erinnert\")"}, {"kategorie": "", "text": "\"Ich hatte derartige Panik - ich hab Bömmerln geschissen wie ein Reh auf der Flucht!\"  3. Ich hab die Angst in kleinen Portionen rausgedrückt - direkt in meine Unterhose!"}]'::jsonb, ''),
  ('da-schdift-vabind-in-fruchtknootn-mit-da-noarbm-und-is-fiad-poinleitung-zuaschdaendich', 'Da Schdift vabind in Fruchtknootn mit da Noarbm und is fiad Poinleitung zuaschdändich!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Der Stift verbindet den Fruchtknoten mit der Narbe und ist für die Pollenleitung zuständig!', '[{"kategorie": "wörtlich, bot.", "text": "\"Der Griffel stellt die Verbindung zwischen dem Fruchtknoten und der Narbe her und leitet die Pollen weiter!\"  2. Der Stylus verbindet die weiblichen Blütenteile und dient als Leitstruktur für den Pollenschlauch!  3. Der Stift ist das Mittelstück der Blüte – er sorgt dafür, dass die Pollen von der Narbe zur Eizelle weitergeleitet werden!"}]'::jsonb, ''),
  ('da-schdift-muass-gaunz-genau-ind-boorung-passn-sunst-woogld-des-gaunze-taeu', 'Da Schdift muass gaunz genau ind Boorung passn, sunst woogld des gaunze Täu!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Stift muss ganz genau in die Bohrung passen, sonst wackelt das ganze Teil!', '[{"kategorie": "wörtlich", "text": "\"Der Passstift muss exakt zur Bohrung passen, sonst ist die Passung nicht formschlüssig!\"  2. Stift und Bohrung müssen toleranzgenau aufeinander abgestimmt sein, um Spiel in der Verbindung zu vermeiden!  3. Der Stift muss sitzen wie der Schlüssel im Schloss – sonst wackelt das ganze Teil!"}]'::jsonb, ''),
  ('wea-hod-ma-schoo-wiida-mein-schdift-gflaadad', 'Wea hod ma schoo wiida mein Schdift gflaadad?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer hat mir schon wieder meinen Stift gefladert?', '[{"kategorie": "wörtlich", "text": "\"Wer hat schon wieder meinen Stift mitgehen lassen?\"  2. Wer hat sich meinen Stift diesmal unter den Nagel gerissen?  3. Mein Stift ist weg – wer hat ihn sich diesmal wieder eingenäht?"}]'::jsonb, ''),
  ('do-geed-aan-da-schdift', 'Do geed aan da Schdift!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da geht einem der Stift!', '[{"kategorie": "wörtlich", "text": "\"Da fährt einem derart die Angst ein, dass der Stuhlgang einsetzt!\" (wobei \"Stift\" in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"Da scheißt man sich vor Angst in die Hose!\"  3. \"Da geht einem der Arsch auf Grundeis!\"  4. \"Da geht einem die Düse!\"  5. \"Da geht einem die Muffe!\""}]'::jsonb, ''),
  ('do-geed-aan-de-muffn', 'Do geed aan de Muffn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da geht einem die Muffen!', '[{"kategorie": "wörtlich", "text": "\"Da fährt einem derart die Angst ein, dass der Stuhlgang einsetzt!\" (wobei [[Muffn]] in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"Da scheißt man sich vor Angst in die Hose!\"  3. \"Da geht einem der Arsch auf Grundeis!\"  4. \"Da geht einem die Düse!\"  5. \"Da geht einem der Stift!\""}]'::jsonb, ''),
  ('do-geed-aan-de-dueuesn', 'Do geed aan de Düüsn!', '', '', '', 'Wiener Gaunersprache', 'Da geht einem die Düse!', '[{"kategorie": "wörtlich", "text": "\"Da fährt einem derart die Angst ein, dass der Arsch pfeift!\" (wobei [[Düse]] in diesem Fall metaphorisch für den After [Anus] steht – also eine derbe Umschreibung des körperlichen Kontrollverlusts)"}, {"kategorie": "", "text": "\"Da scheißt man sich vor Angst in die Hose!\"  3. \"Da geht einem der Arsch auf Grundeis!\"  4. \"Da geht einem der Stift!\"  5. \"Da geht einem die Muffe!\""}]'::jsonb, ''),
  ('i-schreib-imma-mid-bleischdift-do-kauma-noocha-de-foeoela-leichta-ausradian', 'I schreib imma mid Bleischdift - do kauma noocha de Fööla leichta ausradian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich schreib immer mit Bleistift - da kann man nachher die Fehler leichter ausradieren!', '[{"kategorie": "wörtlich", "text": "Ich schreibe immer mit Bleistift - denn da kann man Irrtümer oder Rechtschreibfehler einfach wegradieren!  2. Ich schreib viel lieber mit Bleistift, weil der verzeiht dir Fehler – ein Strich, ein Wischer, weg ist’s!  3. Bleistift eignet sich bei mir am besten zum Schreiben, weil Korrekturen dann schnell und sauber möglich sind!"}]'::jsonb, ''),
  ('do-schdeed-ma-da-bleischdift-aussa', 'Do schdeed ma da Bleischdift aussa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da steht mir der Bleistift raus!', '[{"kategorie": "wörtlich", "text": "\"Da fährt einem derart die Angst ein, dass der Stuhlgang einsetzt!\" (wobei [[Bleistift]] in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"Da scheißt man sich vor Angst in die Hose!\"  3. \"Da geht einem der Arsch auf Grundeis!\"  4. \"Da geht einem die Düse!\"  5. \"Da geht einem der Stift!\""}]'::jsonb, ''),
  ('do-schdeed-ma-da-puri-aussa', 'Do schdeed ma da Puri aussa!', '', '', '', 'Wiener Gaunersprache', 'Da steht mir der Porree raus!', '[{"kategorie": "wörtlich", "text": "\"Da fährt einem derart die Angst ein, dass der Stuhlgang einsetzt!\" (wobei [[Puri]] [Porree] in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"Da scheißt man sich vor Angst in die Hose!\"  3. \"Da geht einem der Arsch auf Grundeis!\"  4. \"Da geht einem die Düse!\"  5. \"Da geht einem der Stift!\""}]'::jsonb, ''),
  ('do-schdeed-ma-da-tschik-aussa', 'Do schdeed ma da Tschik aussa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da steht mir der Tschick raus!', '[{"kategorie": "wörtlich", "text": "\"Da fährt einem derart die Angst ein, dass der Stuhlgang einsetzt!\" (wobei [[Tschick]] [Zigarette] in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"Da scheißt man sich vor Angst in die Hose!\"  3. \"Da geht einem der Arsch auf Grundeis!\"  4. \"Da geht einem die Düse!\"  5. \"Da geht einem der Stift!\""}]'::jsonb, ''),
  ('si-a-schdaungan-laam-ausn-ruckn-druckn', 'si a Schdaungan Laam ausn Ruckn druckn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich eine Stange Lehm aus dem Rücken drücken', '[{"kategorie": "wörtlich", "text": "\"eine lange Wurst aus dem Hintern drücken\" (wobei [[Stange Lehm]] in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"einen Pflock setzen\""}, {"kategorie": "", "text": "\"einen Bleistift rausdrücken\""}, {"kategorie": "", "text": "\"eine [[Wurzen]] scheißen\""}, {"kategorie": "allg.", "text": "\"den Hintern entleeren\" (Stuhlgang haben)"}, {"kategorie": "", "text": "\"seinen Darminhalt zur Welt bringen\""}]'::jsonb, 'Da Mensch kaunn kaa Kultuaweesn ned sei, wäu sunst miassada si ned jeedn Toog a Schdaungan Laam aus Ruckn druckn!'),
  ('da-mensch-kaunn-kaa-kultuaweesn-ned-sei-waeu-sunst-miassada-si-ned-jeedn-toog-a-schdaungan-laam-aus-ruckn-druckn', 'Da Mensch kaunn kaa Kultuaweesn ned sei, wäu sunst miassada si ned jeedn Toog a Schdaungan Laam aus Ruckn druckn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Mensch kann kein Kulturwesen nicht sein, weil sonst müsste er sich nicht jeden Tag eine Stange Lehm aus dem Rücken drücken!', '[{"kategorie": "wörtlich", "text": "Wäre der Mensch ein rein gesitiges Kulturwesen, würde er wohl kaum regelmäßig seinen Darminhalt zur Welt bringen müssen!  2. Wenn der Mensch wirklich so kultiviert wäre, wie er tut, müsste er nicht täglich seine Natur in der Keramikschüssel ablegen!  3. Man redet viel von der hochgeistigen Kultur des Menschen - doch der tägliche Klogang holt uns alle wieder auf den Boden der Realität zurück!"}]'::jsonb, 'si a Schdaungan Laam ausn Ruckn druckn'),
  ('si-a-schdaungan-laam-ausn-kreiz-druckn', 'si a Schdaungan Laam ausn Kreiz druckn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich eine Stange Lehm aus dem Kreuz drücken', '[{"kategorie": "wörtlich", "text": "\"eine lange Wurst aus dem Hintern drücken\" (wobei [[Stange Lehm]] in diesem Fall eine bildhafte, derbe Umschreibung für \"Kackwurst\" ist - wohl in Anspielung  auf deren zylindrische, längliche Form)"}, {"kategorie": "", "text": "\"einen Pflock setzen\""}, {"kategorie": "", "text": "\"einen Bleistift rausdrücken\""}, {"kategorie": "", "text": "\"eine [[Wurzen]] scheißen\""}, {"kategorie": "allg.", "text": "\"den Hintern entleeren\" (Stuhlgang haben)"}, {"kategorie": "", "text": "\"seinen Darminhalt zur Welt bringen\""}]'::jsonb, 'Oida, heit hob I a Schdaungan Laam ausn Kreiz pressd, de ma in Babylon zum Tuambau vawendn hätt kenna!'),
  ('oida-heit-hob-i-a-schdaungan-laam-ausn-kreiz-pressd-de-ma-in-babylon-zum-tuambau-vawendn-haett-kenna', 'Oida, heit hob I a Schdaungan Laam ausn Kreiz pressd, de ma in Babylon zum Tuambau vawendn hätt kenna!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alter, heut hab ich ''ne Stange Lehm aus dem Kreuz gepresst, die man in Babylon zum Turmbau verwenden hätt'' können!', '[{"kategorie": "wörtlich", "text": "\"Alter, heut hab ich ''ne Kackwurst rausgedrückt, die man in Babylon zum Turmbau verwenden hätt'' können!\"  2. Ich sag''s dir, Alter: Mit der Kackwurst, die ich heut rausgeschissen hab, hätten die Babylonier den Turm zu Babel bauen können!  3. Junge, ich hab heut früh ’nen Ziegel rausgepresst, mit dem man in Babylon die Turmmauer zu Babel hätte errichten können!"}]'::jsonb, 'si a Schdaungan Laam ausn Kreiz druckn'),
  ('i-glaub-de-dueuesn-is-zua-waeu-da-muarl-schdoodad-wia-wueued', 'I glaub, de Düüsn is zua, wäu da Muarl schdoodad wia wüüd!', '', '', '', 'Wiener Mechaniker-Slang', 'Ich glaub, die Düse ist zu, weil der Motor stottert wie wild!', '[{"kategorie": "wörtlich", "text": "\"Ich glaub, dass die Düse verstopft ist und der Motor deshalb so unrund läuft!\"  2. Da ist bestimmt wieder Dreck in der Düse, sonst hätte der Motor nicht so viele Aussetzer!  3. Sieht so aus, als wär die Einspritzdüse dicht – denn der Motor stottert ohne Ende!"}]'::jsonb, ''),
  ('du-bist-a-echte-dueuesn-mit-dia-wiads-nii-faad', 'Du bist a echte Düüsn - mit dia wiads nii faad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du bist ''ne echte Düse - mit dir wird''s nie fad!', '[{"kategorie": "wörtlich", "text": "\"Du bist ''ne echte Ulknudel - mit dir wird''s nie langweilig!\"  2. Du bist ein Knallbonbon auf zwei Beinen – bei dir kommt nie Langeweile auf!  3. Du bist ein echtes Original - du bringst immer Schwung in die Bude!"}]'::jsonb, ''),
  ('mia-geed-de-dueuesn', 'Mia geed de Düüsn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mir geht die Düse!', '[{"kategorie": "wörtlich", "text": "\"Ich habe eine Scheißangst!\" (wobei [[Düse]] in diesem Fall metaphorisch für den After [Anus] steht – also eine derbe Umschreibung des körperlichen Kontrollverlusts)"}, {"kategorie": "", "text": "Ich mache mir vor Angst in die Hose !  3. Mir geht der [[Reis]]!  4. Mir geht die [[Muffn]]!"}]'::jsonb, ''),
  ('do-ziagds-da-ois-zsaumm', 'Do ziagds da ois zsaumm!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da zieht es dir alles zusammen!', '[{"kategorie": "wörtlich", "text": "\"Da verkrampft sich alles in dir!\"  2. \"Da zieht sich dir der Magen zusammen!\"  3. \"Da friert dir das Blut in den Adern!\"  4. \"Da läuft dir der kalte Schauer über den Rücken!\"  5. \"Da zieht’s dir die Galle bis in die Stirn!\""}]'::jsonb, ''),
  ('bei-dem-gschdaungn-zaads-da-ois-zsaumm', 'Bei dem Gschdaungn zaads da ois zsaumm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei dem Gestank zieht''s dir alles zusammen!', '[{"kategorie": "wörtlich", "text": "\"Bei dem Gestank verkrampft sich alles in dir!\"  2. Bei dem Gestank dreht es dir den Magen um!  3. Bei dem Gestank zieht es dir die Galle bis in die Stirn!"}]'::jsonb, 'Do ziagds da ois zsaumm!'),
  ('muffnsausn-haasd-nix-aundas-ois-dass-da-de-dueuesn-geed-so-wia-mia-vua-meina-oidn', 'Muffnsausn haasd nix aundas, ois dass da de Düüsn geed - so wia mia vua meina Oidn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Muffensausen heißt nichts anderes, als dass dir die Düse geht - so wie mir vor meiner Alten!', '[{"kategorie": "wörtlich", "text": "\"Muffensausen heißt, dass dir die Galle zittert – so wie mir, wenn meine Alte in der Tür steht!\"  2. \"Muffensausen? Das ist, wenn dir der Hintern auf Grundeis geht – vor allem, wenn sie ‘Liebling, wir müssen reden’ sagt!\"  3. Muffensausen bedeutet, dass du plötzlich ganz dringend weg willst – so wie ich, wenn meine Alte ihre Schwiegermutterstimme auspackt!"}]'::jsonb, ''),
  ('bei-dem-sauweeda-muass-i-ma-an-bauchalwaeama-einehaun-aum-bestn-glueuewein-oda-punsch', 'Bei dem Sauweeda muass I ma an Bauchalwäama einehaun - aum bestn Glüüwein oda Punsch!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bei diesem Sauwetter muss ich mir einen Baucherlwärmer reinhauen - am besten Glühwein oder Punsch!', '[{"kategorie": "wörtlich", "text": "\"Bei dem Sauwetter brauch ich was Warmes im Bauch – am besten Glühwein oder Punsch!\"  2. Das Wetter schreit nach heißem Alkohol – ich brauch Glühwein oder Punsch zum Aufwärmen!  3. Bei der Kälte hilft nur ein innerer Wärmespender – am besten Glühwein oder Punsch!"}]'::jsonb, ''),
  ('tua-ma-a-runde-bauchalhuutschn', 'Tua ma a Runde bauchalhuutschn?', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Tun wir eine Runde baucherlhutschen?', '[{"kategorie": "wörtlich", "text": "\"Wollen wir eine Runde Bauchsport einlegen?\"  2. \"Komm, lass uns die Bäuchlein zum Schwingen bringen!\"  3. Wie wär’s, wenn wir uns gegenseitig das Bäuchlein schaukeln?  4. (scherzhaft für): \"Komm, lass uns miteinanander Sex haben!\""}]'::jsonb, ''),
  ('wos-da-baua-ned-kennd-frissda-ned', 'Wos da Baua ned kennd, frissda ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Was der Bauer nicht kennt, frisst er nicht!', '[{"kategorie": "wörtlich", "text": "\"Neues ist dem Bauer nicht geheuer!\"  2. Vor Neuem scheut der Bauer zurück!  3. \"Alles was nicht nach Schweinsbraten riecht, ist dem Bauer unheimlich!\"  4. ''Tradition statt Innovation'' - sagt der Bauer!"}]'::jsonb, ''),
  ('da-baua-joodld-bein-haamgee', 'Da Baua joodld bein Haamgee!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Bauer jodelt beim Heimgeh''n!', '[{"kategorie": "wörtlich", "text": "\"Wer zu früh jodelt, zieht am Ende oft den Kürzeren!\"  2. \"Man sollte sich nie zu früh freuen!\"  3. \"Man soll den Tag nicht vor dem Abend loben!\""}]'::jsonb, ''),
  ('de-dimmsdn-bauan-haum-de-greessdn-eadaepfaen', 'De dimmsdn Bauan haum de greessdn Eadäpfän!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die dümmsten Bauern haben die größten Erdäpfel!', '[{"kategorie": "wörtlich", "text": "\"Die größten Kartoffeln wachsen auf den Feldern der Dümmsten!\"  2. Das Glück ist mit den Dümmsten!  3. Die Depperten haben s''Glückl!  4. Darauf brauchst du dir nichts einzubilden - das war reines Glück!"}]'::jsonb, ''),
  ('de-deppadn-haums-glick', 'De Deppadn haums Glick!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die Depperten haben ''s Glück!', '[{"kategorie": "wörtlich", "text": "\"Die Dummen haben das Glück!\"  2. Das Glück ist mit den Dümmsten!  3. Die dümmsten Bauern haben die größten Erdäpfel!  4. Darauf brauchst du dir nichts einzubilden - das war reines Glück!"}]'::jsonb, ''),
  ('des-bauangfriiss-schaud-drei-wiara-moeoekmaschin-mit-depression', 'Des Bauangfriiss schaud drei wiara Möökmaschin mit Depression!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieses Bauerngfrieß schaut drein wie ''ne Melkmaschine mit Depression!', '[{"kategorie": "wörtlich", "text": "\"Diese Bauernvisage schaut drein wie ''ne Melkmaschine mit Depression!\"  2. \"Dieses Bauerngsicht hat die Ausstrahlung von einem nassen Kartoffelsack!\"  3. Wenn Grant ein Gesicht bräuchte, dann wär’s dieses Bauerngfrieß!"}]'::jsonb, ''),
  ('waunn-i-so-a-gscheadngfriiss-haedad-wia-du-daed-i-beim-moeoekn-es-liachd-oodraan', 'Waunn I so a Gscheadngfriiss hädad wia du, däd I beim Möökn es Liachd oodraan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich so ein Geschertengfrieß hätte wie du, würde ich beim Melken das Licht abdrehen!', '[{"kategorie": "wörtlich", "text": "\"Hätt'' ich so ''ne Bauernfresse wie du, würde ich beim Melken das Licht abdrehen!\"  2. Wenn ich so ein Bauerngesicht hätte wie du, würd ich mir beim Melken einen Sack über’n Schädel ziehen, damit die Milch nicht sauer wird!  3. Mit deiner Bauernfratze erschreckst du jede Kuh – da flockt die Milch schon beim Melken aus!"}]'::jsonb, ''),
  ('mit-dem-bauanschmaeae-kaunnsd-di-bei-mia-brausn', 'Mit dem Bauanschmää kaunnsd di bei mia brausn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit dem Bauernschmäh kannst dich bei mir brausen!', '[{"kategorie": "wörtlich", "text": "\"Mit der plumpen Masche brauchst du mir erst gar nicht zu kommen!\"  2. Deine Hinterwäldlermasche zieht bei mir nicht!  3. Den Bauerntrick kannst du dir sonst wohin stecken!"}]'::jsonb, ''),
  ('mit-dia-weama-bauanoasch-schbueuen', 'Mit dia weama Bauanoasch schbüün!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit dir werden wir Bauernarsch spielen!', '[{"kategorie": "wörtlich", "text": "\"Dich werden wir vorführen wie einen Bauerntölpel!\"  2. Wir werden dich aussehen lassen wie den letzten Bauerntrottel!  3. Dich werden wir fertigmachen – und zwar vor allen Leuten!  4. Dich werden wir in Grund und Boden stampfen!"}]'::jsonb, ''),
  ('mit-den-bauantrottlschmaeae-haums-di-kriagd', 'Mit den Bauantrottlschmää haums di kriagd?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit diesem Bauerntrottelschmäh haben Sie dich gekriegt?', '[{"kategorie": "wörtlich", "text": "\"Mit dieser Hinterwäldlermasche haben Sie dich gekriegt?\"  2. \"Auf diese plumpe Masche bist du denen reingefallen?\"  3. \"Mit diesem vertrottelten Bauerntrick haben Sie dich erwischt?\""}]'::jsonb, ''),
  ('mit-den-bauantrottlschmaeae-kaunnsd-di-bei-mia-brausn', 'Mit den Bauantrottlschmää kaunnsd di bei mia brausn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit dem Bauerntrottelschmäh kannst dich bei mir brausen!', '[{"kategorie": "wörtlich", "text": "\"Mit der plumpen Masche brauchst du mir erst gar nicht zu kommen!\"  2. Deine Hinterwäldlermasche zieht bei mir nicht!  3. Den vertrottelten Bauerntrick kannst du dir sonst wohin stecken!"}]'::jsonb, ''),
  ('a-schbritza-baumoeoe-reichd-und-schoo-schmeckd-a-jeeds-essn-noch-ualaub-aum-meea', 'A Schbritza Baumöö reichd - und schoo schmeckd a jeeds Essn noch Ualaub aum Meea!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Spritzer Baumöl reicht - und schon schmeckt ein jedes Essen nach Urlaub am Meer!', '[{"kategorie": "wörtlich", "text": "\"Ein Schuss Olivenöl – und schon träumst du beim Essen von Italien!\"   2. Ein paar Tropfen Olivenöl verwandeln deine Mahlzeit in eine Urlaubsreise ans Mittelmeer!  3. Baumöl – der goldene Saft des Ölbaums, der jedes Gericht nach Sonne, Meer und Süden schmecken lässt!"}]'::jsonb, ''),
  ('desmoi-hauma-de-spaghettifressa-3-0-vom-plotz-putzd', 'Desmoi hauma de Spaghettifressa 3:0 vom Plotz putzd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Dieses Mal haben wir die Spaghettifresser 3:0 vom Platz geputzt!', '[{"kategorie": "wörtlich", "text": "\"Diesmal haben wir die Spaghettifresser eingekocht – 3:0 al dente!\"  2. \"Die Italiener haben wir diesmal weichgekocht wie Spaghetti - 3:0, klarer Heimsieg!\"  3. Diesmal haben wir die Pasta-Fraktion 3:0 auseinandergenudelt!"}]'::jsonb, ''),
  ('i-haass-kolaric-du-haasst-kolaric-warum-soongs-zu-dia-tschuusch', 'I haass Kolaric, du haasst Kolaric - Warum soongs zu dia Tschuusch?', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ich heiß Kolaric, du heißt Kolaric - warum sagen sie zu dir ''Tschusch?', '[{"kategorie": "wörtlich", "text": "\"Ich heiß Kolaric und du auch – warum nennen sie dich trotzdem ‚Tschusch‘?\"  (Anfang der 1970er-Jahre sorgte ein Plakat für Aufsehen: Ein kleiner Bub fragt einen fremd aussehenden Mann – „I haaß Kolaric, du haaßt Kolaric. Warum sogn’s zu dir Tschusch?“ Es sollte für mehr Toleranz gegenüber Gastarbeiter:innen werben, die oft abwertend als „Tschuschen“ bezeichnet wurden)"}, {"kategorie": "", "text": "Wir heißen gleich, aber sie schimpfen nur dich – warum?  3. Wenn wir beide Kolaric heißen, wieso behandeln sie dich dann anders?"}]'::jsonb, ''),
  ('de-leidln-aus-tschuuschien-haum-vueue-mea-heaz-ois-de-gaunzn-schwoobm-und-preissn', 'De Leidln aus Tschuuschien haum vüü mea Heaz ois de gaunzn Schwoobm und Preissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Leute aus Tschuschien haben viel mehr Herz als die ganzen Schwaben und Preußen!', '[{"kategorie": "wörtlich", "text": "\"Die Leute vom Balkan haben viel mehr Herz als die ganzen Schwaben und Preußen!\"  2. Die Leute vom Balkan sind viel wärmer im Herzen als die Nord- oder Süddeutschen!  3. Vom Balkan kommt das Gefühl – bei den Schwaben und Preußen eher das Formular!"}]'::jsonb, ''),
  ('mei-tschikvaasn-is-volla-ois-mei-eiskostn', 'Mei Tschikvaasn is volla ois mei Eiskostn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Meine Tschickvase ist voller als mein Eiskasten!', '[{"kategorie": "wörtlich", "text": "\"Mein Aschenbecher ist voller als mein Kühlschrank!\"  2. \"Mein Ascher ist überfüllt, doch der Eiskasten ist leer!\"  3. Im Ascher glimmt das Leben – im Kühlschrank gähnt die Leere!  4. Zum Rauchen hab ich genug - nur zum Essen gibt''s nix mehr!"}]'::jsonb, ''),
  ('im-tschiktriachal-zichd-i-boid-unkraud-foeoed-nua-noo-a-bissl-eadn', 'Im Tschiktriachal zichd I boid Unkraud - fööd nua noo a bissl Eadn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Im Tschicktrücherl zücht'' ich bald Unkraut – fehlt nur noch ein bisschen Erde!', '[{"kategorie": "wörtlich", "text": "\"Im Aschentrögchen züchte ich bald Unkraut - fehlt nur noch ein bisschen Erde!\"  2. In meinem Aschenbecher wächst schon fast ''ne Wiese – fehlt nur noch ein bisschen Erde und Wasser!  3. Mein Ascher schaut aus wie ein Blumenkisterl für Nikotinsüchtige!"}]'::jsonb, ''),
  ('krepian-soist-wiara-hund', 'Krepian soist wiara Hund!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Krepieren sollst du wie ein Hund!', '[{"kategorie": "wörtlich", "text": "\"Verrecken sollst du wie ein räudiger Köter!\"  2. \"Zugrunde gehen sollst du wie ein herrenloser Hund!\"  3. \"Der Tod soll dich holen wie einen streunenden Hund!\""}]'::jsonb, ''),
  ('mei-untagattn-is-beim-woschn-umd-hoefte-eigaungan-und-zu-an-echtn-eiabeissa-vakumman', 'Mei Untagattn is beim Woschn umd Höfte eigaungan und zu an echtn Eiabeissa vakumman!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine Unterhose ist beim Waschen um die Hälfte eingegangen und zu einem echten Eierbeißer verkommen!', '[{"kategorie": "wörtlich", "text": "\"Meine Unterhose ist beim Waschen um die Hälfte eingegangen und ist jetzt ein echter Hodenquetscher!\"  2. Meine Boxershorts hat sich beim Waschen so zusammengezogen, dass sie mir jetzt bei jedem Schritt die Eier quetscht!  3. Meine Unterhose ist nach dem Waschen um die Hälfte eingegangen und zu einem [[Beidlschnürer]] verkommen!"}]'::jsonb, ''),
  ('wea-echte-weana-gmiadlichkeid-daleebm-wueue-muass-amoi-auf-aan-heirichnbaangal-gsessn-sei', 'Wea echte Weana Gmiadlichkeid daleebm wüü, muass amoi auf aan Heirichnbaangal gsessn sei!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wer echte Wiener Gemütlichkeit erleben will, muss einmal auf einem Heurigenbankerl gesessen sein!', '[{"kategorie": "wörtlich", "text": "\"Wer authentische Wiener Gastlichkeit erleben möchte, sollte einmal auf einer traditionellen Heurigenbank Platz genommen haben!\"  2. Echtes Wiener Lebensgefühl spürt man am besten beim Sitzen auf einer kleinen Holzbank im Heurigen!  3. Zwischen Weinreben und Lachen liegt das Heurigenbankerl – und dort wohnt die echte Wiener Gemütlichkeit!"}]'::jsonb, ''),
  ('dea-soi-doch-vareckn-so-wia-mi-dea-behaundld-hod', 'Dea soi doch vareckn - so wia mi dea behaundld hod!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der soll doch verrecken - so wie mich der behandelt hat!', '[{"kategorie": "wörtlich", "text": "\"So wie der mich behandelt hat, soll er verrecken!\"  2. Der kann von mir aus krepieren - bei alldem, was er mir angetan hat!  3. Dem wünsch ich, dass er jämmerlich zugruinde geht - nach alldem, was er mir angetan hat!"}]'::jsonb, ''),
  ('vareck-doch-du-oelaendiga-bastard', 'Vareck doch, du öländiga Bastard!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Verreck'' doch, du eledniger Bastard!', '[{"kategorie": "wörtlich", "text": "\"Fahr zur Hölle, du elender Bastard!\"  2. Hau ab und krepier unter ''nem Misthaufn, du Bastard!  3. Verpiss dich und krepiere irgendwo weit weg von mir, du elender Dreckskerl!  4. Verreck mit Anlauf, du Arschgeige!"}]'::jsonb, ''),
  ('des-mentsch-is-total-valuudad-seits-mit-dem-typn-zsaumm-is', 'Des Mentsch is total valuudad, seits mit dem Typn zsaumm is!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Mädel ist total verludert, seit sie mit dem Typen zusammen ist!', '[{"kategorie": "wörtlich", "text": "\"Seit sie mit dem Typen zusammen ist, geht''s mit dem Mädel total bergab!\"  2. Das Mädel ist total verkommen, seit sie mit dem Typen geht!  3. Seit der Typ in ihr Leben getreten ist, verliert sich das Mädel komplett!  4. Das Mädel lässt sich total gehen, seit sie mit diesem Typen zusammen ist!"}]'::jsonb, ''),
  ('de-bootschn-schdreckn', 'de Bootschn schdreckn', '', '', '', 'Grundwortschatz Wienerisch', 'die Patschen strecken', '[{"kategorie": "wörtlich", "text": "\"die Pantoffel aufstellen\""}, {"kategorie": "allg., in Bezug auf Dinge", "text": "\"den Geist aufgeben\", \"sich verabschieden\", \"hopsgehen\""}, {"kategorie": "in Bezug auf Personen", "text": "zusammenklappen, wegkippen, flachliegen, unter''m Tisch liegen"}, {"kategorie": "scherzhaft für", "text": "sterben, das Zeitliche segnen, [[a]] Bangal reissn, [[ins]] Groos beissn, [[maukas]] gee, [[si]] niidaleeng, [[in]] Leffä oogeebm, [[ookrotzn]],  [[si]] de Eadäpfän von unt auschaun"}]'::jsonb, 'Mei oida Bülligsduafa Feanseea hod de Bootschn gschdreckd - woa ää schoo Zeit fia wos Neichs!'),
  ('mei-oida-buelligsduafa-feanseea-hod-de-bootschn-gschdreckd-woa-aeae-schoo-zeit-fia-wos-neichs', 'Mei oida Bülligsduafa Feanseea hod de Bootschn gschdreckd - woa ää schoo Zeit fia wos Neichs!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mein alter Billigsdorfer-Fernseher hat die Patschen g’streckt – war eh schon Zeit für was Neues!', '[{"kategorie": "wörtlich", "text": "\"Meine alte Bilig-Glotzkiste hat den Geist aufgegeben - war eh schon Zeit, was Neues zu kaufen!\"  2. Mein alter Fernseher aus der Ramschkiste ist hopsgegangen – war aber eh schon Zeit für ein Upgrade!  3. Meine Uralt-Glotze hat sich endgültig verabschiedet - Zeit, sicvh was Neues anzuschaffen!"}]'::jsonb, 'de Bootschn schdreckn'),
  ('waunn-dea-noo-an-liita-saufd-schdreckda-heit-sicha-noo-de-bootschn', 'Waunn dea noo an Liita saufd, schdreckda heit sicha noo de Bootschn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der noch einen Liter säuft, streckt er heut sicher noch die Patschen!', '[{"kategorie": "wörtlich", "text": "\"Wenn der noch einen Liter reinkippt, liegt er heute bald unter’m Tisch!\"  2. Noch ein Liter, und der kippt uns weg wie ein nasser Sack!  3. Noch ein Glas, und er segnet das Zeitliche – mit vier Promille im Blut!"}]'::jsonb, 'de Bootschn schdreckn'),
  ('da-hansi-hod-de-bootschn-gschdreckd-jetzt-liigda-woogrechd-in-da-schdockfinstan', 'Da Hansi hod de Bootschn gschdreckd - jetzt liigda woogrechd in da Schdockfinstan!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Hansi hat die Patschen gestreckt - jetzt liegt er waagrecht in der Stockfinstern!', '[{"kategorie": "wörtlich", "text": "\"Der Johann hat das Zeitliche gesegnet – jetzt liegt er waggrecht in der Erde und schaut sich die Erdäpfel von unten an!\"  2. Der Hansl hat die Augen für immer geschlossen – sein neues Zuhause ist jetzt die ewige Finsternis!  3. Der Hansl hat sich in die ewigen Jagdgründe verabschiedet und liegt jetzt sicher waagrecht in der Himmelswiese!"}]'::jsonb, ''),
  ('de-bootschn-ausschdreckn', 'de Bootschn ausschdreckn', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Patschen ausstrecken', '[{"kategorie": "wörtlich", "text": "\"die Pantoffel von sich strecken\""}, {"kategorie": "scherzhaft für", "text": "\"die Füße ausstrecken\", sich zurücklehnen, eine Pause einlegen, durchschnaufen, relaxen"}]'::jsonb, ''),
  ('noch-da-hockn-schdreck-i-zeaschd-amoi-de-bootschn-aus-und-schoid-de-hianschaukl-ei', 'Noch da Hockn schdreck I zeaschd amoi de Bootschn aus und schoid de Hianschaukl ei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach der Hacken streck ich zuerst einmal die Patschen aus und schalt'' die Hirnschaukel ein!', '[{"kategorie": "wörtlich", "text": "\"Nach der Arbeit streck ich erst einmal die Füße aus und schalt'' die Glotze ein!\"  2. Nach der Arbeit leg ich mich erst mal hin, streck die Füße aus und lass den Fernseher für mich denken!  3. Feierabend heißt für mich: Patschen hoch und Flimmerkiste an!"}]'::jsonb, 'de Bootschn ausschdreckn'),
  ('de-bootschn-beidln', 'de Bootschn beidln', '', '', '', 'Tod und Sterben auf Wienerisch', 'die Patschen beuteln', '[{"kategorie": "wörtlich", "text": "\"die Pantoffel abbeuteln\""}, {"kategorie": "scherzhaft für", "text": "sterben, das Zeitliche segnen, [[a]] Bangal reissn, [[ins]] Groos beissn, [[maukas]] gee, [[si]] niidaleeng, [[in]] Leffä oogeebm, [[ookrotzn]],  [[si]] de Eadäpfän von unt auschaunsterben, [[de]] Wiama fiadan"}]'::jsonb, 'Waunn I amoi de Bootschn beidln muass, daunn hauds mi ind Gruabm, Deckel drauf, und a Rua is!'),
  ('waunn-i-amoi-de-bootschn-beidln-muass-daunn-hauds-mi-ind-gruabm-deckel-drauf-und-a-rua-is', 'Waunn I amoi de Bootschn beidln muass, daunn hauds mi ind Gruabm, Deckel drauf, und a Rua is!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn ich einmal die Patschen abbeuteln muss, dann haut mich in die Grube, Deckel drauf und Ruhe im Karton!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich mal abkratze, dann schmeißt mich in das Loch, Erde drüber und Ende im Geläut!\"  2. Wenn ich mal den Löffel abgebe, dann packt mich in die Kiste, versenkt sie und fertig ist die Laube!  3. Wenn ich mal hopsgehe, dann ab in die Grube, zuschütten und Ruhe im Bunker!"}]'::jsonb, 'de Bootschn beidln'),
  ('a-rua-is', 'A Rua is!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Eine Ruhe ist!', '[{"kategorie": "wörtlich", "text": "\"Ruhe jetzt, aber sofort!\"  2. \"Ruhe im Karton!\"  3. \"Klappe zu - und Sense!\"  4. \"Ruhe im Bunker!\"  5. \"Schnauze jetzt!\""}]'::jsonb, ''),
  ('a-wuam-hod-kaane-aung-owa-ea-schbiads-liachd-mid-da-haut', 'A Wuam hod kaane Aung, owa ea schbiads Liachd mid da Haut!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Ein Wurm hat keine Augen, aber er spürt das Licht mit der Haut!', '[{"kategorie": "wörtlich", "text": "\"Würmer besitzen keine Augen, nehmen Lichtreize jedoch über ihre Haut wahr!\"  2. Obwohl der Wurm keine Augen hat, reagiert er empfindlich auf Licht, das er mit der Haut erkennt!  3. Ein Wurm sieht nichts, aber er merkt, wenn es hell wird – mit seiner Haut!"}]'::jsonb, ''),
  ('si-an-wuam-schdessn', 'si an Wuam schdessn', '', '', '', 'Echte Wiener Schmähperlen', 'sich einen Wurm stoßen', '[{"kategorie": "wörtlich", "text": "\"sich eine Zigarette in den Mund schieben\""}, {"kategorie": "", "text": "\"sich eine Zigarette anrauchen\""}, {"kategorie": "", "text": "[[si an Tschik auhaazn]]"}]'::jsonb, 'Des Woatn geed ma aum Oasch - kumm, schdess ma uns dawäu an Wuam!'),
  ('des-woatn-geed-ma-aum-oasch-kumm-schdess-ma-uns-dawaeu-an-wuam', 'Des Woatn geed ma aum Oasch - kumm, schdess ma uns dawäu an Wuam!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das Warten geht mir am Arsch - komm, stoßen wir uns derweil einen Wurm!', '[{"kategorie": "wörtlich", "text": "\"Das Warten geht mir mächtig auf den Keks - komm, schieben wir uns derweil eine Zigarette in den Mund!\"  2. Ich kann dieses ewige Warten echt nicht mehr ertragen – lass uns derweil eine rauchen gehen!  3. Ich werd noch wahnsinnig vor lauter Warten – lass uns rausgehen und eine rauchen!"}]'::jsonb, 'A Wuam hod kaane Aung, owa ea schbiads Liachd mid da Haut!'),
  ('den-sei-wuam-traud-si-nua-ausse-waunns-dunkl-is-und-kaana-zuaschaud', 'Den sei Wuam traud si nua ausse, waunns dunkl is und kaana zuaschaud!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Wurm von ihm traut sich nur raus, wenn’s dunkel ist und keiner zuschaut!', '[{"kategorie": "wörtlich", "text": "\"Sein Würmchen kommt nur raus, wenn keiner hinschaut und das Licht aus ist!\"  2. Sein Glied ist eher vom schüchternen Typ – zeigt sich nur, wenn’s dunkel ist und keiner zuschaut!  3. Seinen Mini-Max da unten holt er nur bei Dunkelheit aus der Hose - hat Angst vor Licht und Publikum!"}]'::jsonb, ''),
  ('de-wiama-fiadan', 'de Wiama fiadan', '', '', '', 'Tod und Sterben auf Wienerisch', 'die Würmer füttern', '[{"kategorie": "wörtlich", "text": "\"als Wurmfutter dienen\""}, {"kategorie": "scherzhaft für", "text": "tot sein, begraben sein, unter der Erde liegen, \"die Radieschen von unten düngen\", [[si]] de Eadäpfän von unt auschaun"}]'::jsonb, 'si de Eadäpfän von unt auschaun'),
  ('da-fraunz-liigd-jetztd-aum-zentraeu-und-fiadad-de-wiama', 'Da Fraunz liigd jetztd aum Zenträu und fiadad de Wiama!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Franz liegt jetzt am Zentral[friedhof] und füttert die Würmer!', '[{"kategorie": "wörtlich", "text": "\"Der Franz liegt jetzt am Zentralfriedhof und düngt jetzt die Radieschen von unten!\"  2. Der Franz liegt jetzt unter der Erde und füttert die Würmer!  3. Der Franz liegt jetzt am Zentralfriedhof und schaut sich die Erdäpfel von unten an!"}]'::jsonb, ''),
  ('de-aumschl-hod-des-wiamal-schoo-im-blick-a-schnoeoes-fruaschduck', 'De Aumschl hod des Wiamal schoo im Blick - a schnöös Fruaschduck!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Amsel hatte das Würmchen schon im Blick – ein schnelles Frühstück!', '[{"kategorie": "wörtlich", "text": "\"Das Würmchen war längst im Visier der Amsel – ein schnelles Frühstück war ihr sicher!\" Kaum guckte das Würmchen aus der Erde, war auch schon die Amsel zur Stelle - ein schnelles Frühstück!\"  3. Die Amsel hatte den kleinen Wurm bereits erspäht – eine leichte Beute für den Morgen!"}]'::jsonb, ''),
  ('dea-tuad-auf-oobaschdecha-dabei-woond-hinta-sein-hoosntial-nuara-klaans-wiamal', 'Dea tuad auf Oobaschdecha - dabei woond hinta sein Hoosntial nuara klaans Wiamal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der tut auf Oberstecher - dabei wohnt hinter seinem Hosenschlitz nur ein kleines Würmchen!', '[{"kategorie": "wörtlich", "text": "\"Der tut groß auf Ober-Casanova – dabei versteckt sich unterm Hosenstall nur ein kleines Würmchen!\"  2. Der gibt sich als großer Ober-Puderant – doch in Wirklichkeit verbirgt sich da unten nur ein mickriges Würmchen von ein paar Zentimetern!  3. Der spielt den großen Verführer – dabei bringt’s sein Mini-Max nur auf ein paar Zentimeter!"}]'::jsonb, ''),
  ('du-oams-wiamal-du', 'Du oams Wiamal, du!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du armes Würmerl, du!', '[{"kategorie": "wörtlich", "text": "\"Du armes Würmchen, du!\"  2. \"Du armes Seelchen!\"  3. (klar negativ konnotiert): \"Du bemitleidenswerte Gestalt!\"  4. \"Du jämmerliches Würstchen, du!\"  5. \"Du armseliger Versager!\""}]'::jsonb, ''),
  ('an-wuam-in-da-marueuen-haum', 'an Wuam in da Marüün haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Wurm in der Marille haben', '[{"kategorie": "wörtlich", "text": "\"einen Wurm im Kopf haben\""}, {"kategorie": "scherzhaft für", "text": "einen Dachschaden haben, einen Vogel haben, einen Sprung in der Schüssel haben, an [[Glaumsch]] haum, [[an]] Ditscha haum, [[an]] Poscha haum, [[an]] Klopfa haum, [[an]] Klescha haum"}]'::jsonb, 'Dea hod an Wuam in da Marüün!'),
  ('du-wueuesd-di-scheidn-lossn-host-an-wuam-inda-marueuen', 'Du wüüsd di scheidn lossn? - Host an Wuam inda Marüün?', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Du willst dich scheiden lassen? - Hast du ''nen Wurm in der Marille?', '[{"kategorie": "wörtlich", "text": "\"Du willst dich scheiden lassen? – Bist du deppert oder was?!\"  2. \"Du willst die Scheidung?! – Sag mal, hast du einen Sprung in der Schüssel?\"  3. \"Du willst dich scheiden lassen? – Also entweder hast du Fieber oder ''nen Wurm im Hirnkastl!\""}]'::jsonb, 'an Wuam in da Marüün haum'),
  ('da-datzlwuam-hoib-schlaungan-hoib-raubkotz-kennd-kaan-schmeaz-nua-teedliche-gia', 'Da Datzlwuam - hoib Schlaungan, hoib Raubkotz - kennd kaan Schmeaz - nua teedliche Gia!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Tatzelwurm - halb Schlange, halb Raubkatze - kennt keinen Schmerz - nur tödliche Gier!', '[{"kategorie": "wörtlich", "text": "\"Der Tatzelwurm - halb Bestie, halb Fluch – spürt kein Leid, nur unstillbares Verlangen!\"  2. Der Tatzelwurm – eine Kreatur ohne Herz – jagt nicht aus Not, sondern aus Lust am Verderben!  3. Ein Wesen aus Finsternis und Gift – der Tatzelwurm kennt kein Mitleid, nur die Gier nach Fleisch!"}]'::jsonb, ''),
  ('waunn-di-da-beisswuam-friassd-schbuckkda-di-glei-wiida-aus-und-wiad-vegetaria-auf-leebmszeit', 'Waunn di da Beisswuam friassd, schbuckkda di glei wiida aus und wiad Vegetaria auf Leebmszeit!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn dich der Beißwurm frisst, spuckt er dich gleich wieder aus und wird Vegetarier auf Lebenszeit!', '[{"kategorie": "wörtlich", "text": "\"Wenn dich der Tatzelwurm frisst, kotzt er dich gleich wieder aus und schwört dem Fleisch für immer ab!\"  2. Wenn dich der Tatzelwurm erwischt, verliert er auf der Stelle den Appetit – auf alles, was kreucht und fleucht!  3. Wenn dich der Tatzelwurm frisst, spuckt er dich gleich wieder aus, macht drei Kreuze und wird Frutarier!"}]'::jsonb, ''),
  ('do-woara-beisswuam-im-goatn-ea-woid-eam-datreedn-jetzt-isa-tood', 'Do woara Beisswuam im Goatn - ea woid eam datreedn, jetzt isa tood!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Da war ein Beißwurm im Garten - er wollte ihn zertreten, jetzt ist er tot!', '[{"kategorie": "wörtlich", "text": "\"Da war eine Giftschlange im Garten - er wollte sie zertreten, jetzt ist er tot!\"  2. Da war eine Giftschlange im Garten, er hat auf Rambo gemacht und hingetreten - jetzt füttert er die Würmer!  3. Da war eine Kreuzotter unterm Strauch und er ist draufgetreten - jetzt schaut er sich jetzt die Erdäpfel von unten an!"}]'::jsonb, ''),
  ('mei-oide-is-a-beisswuam-owa-mittlawaeun-bin-i-geeng-ia-gift-immun', 'Mei Oide is a Beisswuam - owa mittlawäun bin I geeng ia Gift immun!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Meine Alte ist ein Beißwurm - aber mittlerweile bin ich gegen ihr Gift immun!', '[{"kategorie": "wörtlich", "text": "\"Meine Alte ist ''ne Giftschlange - aber mittlerweile bin ich gegen ihr Gift immun!\"  2. Meine Alte speit Gift wie eh und je – aber ich hab längst Hornhaut auf der Seele!  3. Meine Alte ist und bleibt ’ne Giftschlange – aber ich hab innerlich längst Gegengift entwickelt!"}]'::jsonb, ''),
  ('ins-groos-beissn', 'ins Groos beissn', '', '', '', 'Tod und Sterben auf Wienerisch', 'ins Gras beißen', '[{"kategorie": "wörtlich", "text": "\"für immer mit dem Gesicht auf dem Gras zu liegen kommen\""}, {"kategorie": "scherzhaft für", "text": "sterben, das Zeitliche segnen, [[a]] Bangal reissn, [[de]] Bootschn schdreckn, [[maukas]] gee, [[si]] niidaleeng, [[in]] Leffä oogeebm, [[ookrotzn]],  [[si]] de Eadäpfän von unt auschaunsterben, [[de]] Wiama fiadan"}]'::jsonb, 'Dea woid in fettn Broodn allaanich oogreifn - owa schdott da Marii hoda jetzd Blei gschnupfd und ins Groos bissn!'),
  ('dea-woid-in-fettn-broodn-allaanich-oogreifn-owa-schdott-da-marii-hoda-jetzd-blei-gschnupfd-und-ins-groos-bissn', 'Dea woid in fettn Broodn allaanich oogreifn - owa schdott da Marii hoda jetzd Blei gschnupfd und ins Groos bissn!', '', '', '', 'Wiener Gaunersprache', 'Der wollte den fetten Braten allein abgreifen – doch statt Geld hat er Blei geschnupft und ins Gras gebissen!', '[{"kategorie": "wörtlich", "text": "\"Der wollte den ganzen Schnitt von der Beute für sich allein – jetzt hat er statt Zaster nur Blei gefressen und ins Gras gebissen!\"  2. Er wollte den Deal alleine drehen – dabei ist er direkt in die Blei-Dusche gelaufen und hat ins Gras gebissen!  3. Er wollte den ganzen Batzen allein einsacken – dann kam die Bleidusche, er hat ins Gras gebissen und liegt jetzt zwei Meter tiefer!"}]'::jsonb, 'ins Groos beissn')
